  const users=[{id:'admin1',name:'Fomalhaut',username:'fomalhaut',role:'admin'},{id:'admin2',name:'Олександра',username:'oleksandra',role:'admin'},{id:'actor1',name:'Софія',username:'sofia_voice',role:'actor'},{id:'actor2',name:'Андрій',username:'andrii_voice',role:'actor'},{id:'actor3',name:'Марія',username:'maria_voice',role:'actor'},{id:'sound1',name:'Максим',username:'max_sound',role:'engineer'}];
  const projects=[{id:'madoka',title:'Мадока Маґіка',code:'Madoka',description:'Магія, що починається з голосу.',chat_id:null,thread_id:null},{id:'baki',title:'Боєць Бакі',code:'Baki',description:'Другий сезон · Найвеличніший турнір',chat_id:null,thread_id:null},{id:'morita',title:'Моріта Небалакуча',code:'Morita',description:'Тихі історії, знайомі голоси.',chat_id:null,thread_id:null}];
  const specs=[['madoka',3,'Мамі Томое','actor1','review',2],['madoka',3,'Мадока Канаме','actor3','approved',2],['madoka',3,'Хомура Акемі','actor2','working',1],['madoka',2,'Мамі Томое','actor1','approved',-2],['madoka',2,'Мадока Канаме','actor3','approved',-2],['madoka',4,'Кюбей','actor2','todo',4],['baki',5,'Бакі Ханма','actor2','working',-1],['baki',5,'Кодзуе','actor1','todo',3],['baki',4,'Бакі Ханма','actor2','approved',-4],['morita',1,'Маю Моріта','actor3','approved',-3],['morita',1,'Мікі Муракоші','actor1','working',3]];
  const tasks=specs.map((a,i)=>({id:'task'+i,project_id:a[0],episode:a[1],character:a[2],assignee:a[3],status:a[4],deadline:tomorrow(a[5]),note:''}));
  const takes=tasks.filter(t=>['approved','review'].includes(t.status)).map((t,i)=>({id:'take'+i,task_id:t.id,version:i===0?2:1,filename:`${projects.find(p=>p.id===t.project_id).code}_E${String(t.episode).padStart(2,'0')}_${t.character.replaceAll(' ','_')}_v01.flac`,bytes:(30+i*7)*1048576,metadata:{sampleRate:48000,bits:24,channels:1},created_at:tomorrow(-i),demo:true}));
  return {mode:'demo',users,projects,tasks,takes,jobs:[],user:users[0],notificationErrors:[]};
