const transferQueue=[];let transferRunning=false;
const transferPending=()=>transferQueue.some(x=>['queued','uploading','processing','checking'].includes(x.status));
function transferButton(){const n=transferQueue.filter(x=>['queued','uploading','processing','checking'].includes(x.status)).length;return `<button class="iconbtn transfer-button" data-action="transfers" aria-label="Завантаження${n?': '+n:''}" title="Завантаження">${icon('upload')}${n?`<span class="notice-dot"></span>`:''}</button>`;}
function updateTransfers(){for(const x of transferQueue)if(x.status==='done'&&!x.completedAt){x.completedAt=Date.now();setTimeout(updateTransfers,8000);}const b=$('[data-action=transfers]');if(b)b.outerHTML=transferButton();if($('#transfer-list'))$('#transfer-list').innerHTML=transferRows();const tg=window.Telegram?.WebApp;if(tg?.initData&&tg.isVersionAtLeast?.('6.2')){if(transferPending()||pendingUpload)tg.enableClosingConfirmation();else tg.disableClosingConfirmation();}}
function transferRows(){return transferQueue.filter(x=>x.status!=='cancelled'&&!(x.status==='done'&&Date.now()-x.completedAt>=8000)).map(x=>`<article class="notification-card"><strong>${escape(x.file.name)}</strong><p>${escape(project(state.tasks.find(t=>t.id===x.taskId)?.project_id)?.title)} · ${escape(x.message||({queued:'У черзі',uploading:'Передавання на сервер',processing:'Обробка й надсилання в Telegram',done:'Файл надіслано',failed:'Помилка',cancelled:'Прибрано з черги'})[x.status])}</p><progress max="100" value="${x.percent||0}"></progress><small>${x.status==='uploading'?Math.floor(x.percent)+'% передано':' '}</small>${x.status==='failed'&&!x.batch?`<button class="button small" data-action="transfer-retry" data-id="${x.id}">Повторити</button>`:''}${['queued','failed'].includes(x.status)?`<button class="button small" data-action="transfer-cancel" data-id="${x.id}">Скасувати</button>`:''}</article>`).join('')||empty('У цій вкладці немає завантажень.');}
function transfersModal(){modal('Завантаження',`<p>Можна закрити це вікно і працювати далі. Залиште сам додаток відкритим до завершення передавання. Після передавання обробка триває на сервері.</p><div id="transfer-list">${transferRows()}</div>${state.jobs.filter(j=>!['done'].includes(j.status)&&!transferQueue.some(x=>x.jobId===j.id)).map(j=>`<div class="notice">Черга сервера · ${escape(state.tasks.find(t=>t.id===j.task_id)?.character)}: ${escape(j.error||j.status)}</div>`).join('')}`);}
function uploadRequest(taskId,file,headers,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/tasks/'+encodeURIComponent(taskId)+'/upload');xhr.timeout=3600000;for(const [k,v] of Object.entries(headers))xhr.setRequestHeader(k,v);xhr.upload.onprogress=e=>onProgress?.(e.lengthComputable?e.loaded/e.total*100:0);xhr.onerror=()=>reject(new Error('З’єднання перервано. Перевірте чергу сервера перед повторною спробою.'));xhr.ontimeout=()=>reject(new Error('Час передавання вичерпано. Перевірте чергу сервера.'));xhr.onload=()=>{let r;try{r=JSON.parse(xhr.responseText);}catch{return reject(new Error('Сервер не повернув результат. Перевірте чергу.'));}if(xhr.status>=200&&xhr.status<300)resolve(r);else reject(new Error(r.error||'Помилка надсилання'));};xhr.send(file);});}
async function pumpTransfers(){if(transferRunning)return;transferRunning=true;try{for(const item of transferQueue){if(item.status!=='queued')continue;item.status='uploading';updateTransfers();try{await submitFile(item.taskId,item.file,item.replaces,false,false,item);item.status='done';item.percent=100;item.message='Файл успішно надіслано';notify('Завантажено: '+item.file.name);if(demo){state.notifications.push({id:newID(),key:'upload:'+item.id,user_id:state.user.id,message:'Завантажено: '+item.file.name,read_at:null,created_at:new Date().toISOString(),status:'sent'});persist();}updateNoticeBell();}catch(e){item.status='failed';item.message=e.message;notify('Не вдалося завантажити '+item.file.name+'. Відкрийте чергу вгорі.');}updateTransfers();}}finally{transferRunning=false;updateTransfers();}}
async function enqueueFiles(taskId,files,replaces){if(pendingUpload)throw new Error('Спочатку завершіть розподіл субтитрів.');const all=[...transferQueue.filter(x=>['queued','uploading','processing'].includes(x.status)).map(x=>x.file),...files];await assertDistinctFiles(all);for(const file of files)transferQueue.push({id:newID(),taskId,file,replaces,status:'queued',percent:0});updateTransfers();void pumpTransfers();notify('Файли додано до черги. Прогрес — у значку завантаження вгорі.');}

let uploadPreviewUrl=null,activeTaskId=null,inTaskView=false,showOthers=false,modalRevision=0;
