async function finishTaskAction(){const id=activeTaskId;await refresh();if(id&&state.tasks.some(t=>t.id===id))productionTask(state.tasks.find(t=>t.id===id));else closeSheet();}
const currentRoute=()=>({page,projectId:selectedProject,tab:projectTab,filter,q:search});
function applyRoute(route){page=route.page;selectedProject=route.projectId;projectTab=route.tab||'tasks';filter=route.filter||'all';search=route.q||'';}
function rememberRoute(){history.replaceState({...history.state,studio:true,route:currentRoute(),scroll:window.scrollY},'',encodeRoute(currentRoute()));}
function syncBack(){const tg=window.Telegram?.WebApp;if(tg?.initData&&tg.BackButton){if($('#modal').open||page!=='overview'||search)tg.BackButton.show();else tg.BackButton.hide();}}
function navigate(route,{replace=false}={}){
  rememberRoute();const depth=history.state?.depth||0;applyRoute({page:'overview',projectId:null,tab:'tasks',filter:'all',q:'',...route});
  history[replace?'replaceState':'pushState']({studio:true,route:currentRoute(),depth:replace?depth:depth+1,scroll:0},'',encodeRoute(currentRoute()));render();window.scrollTo({top:0});
}
function closeSheet(){modalRevision++;if(activeTaskId&&!inTaskView&&!pendingUpload){productionTask(state.tasks.find(t=>t.id===activeTaskId));return;}activeTaskId=null;inTaskView=false;$('#modal').close();if(history.state?.sheet)history.back();syncBack();}
function goBack(){if($('#modal').open)return closeSheet();if((history.state?.depth||0)>0)history.back();else navigate({page:page==='project'?'projects':'overview'},{replace:true});}
function setUploadBusy(value){pendingUpload=value;const tg=window.Telegram?.WebApp;if(tg?.initData&&tg.isVersionAtLeast?.('6.2')){if(value)tg.enableClosingConfirmation();else tg.disableClosingConfirmation();}}
function mainContent(){return search.trim()?searchPage():page==='overview'?overview():page==='projects'?projectsPage():page==='project'?projectPage():page==='tasks'?tasksPage():page==='files'?filesPage():page==='team'?teamPage():page==='deadlines'?deadlinesPage():page==='analytics'?analyticsPage():settingsPage();}
function renderMainUnsafe(){const content=$('#content');if(content){content.className='content '+(search.trim()?'page-search':'page-'+page);content.innerHTML=mainContent();}syncBack();}
function searchPage(){
  const found=searchStudio(state,search),count=found.projects.length+found.tasks.length+found.takes.length+found.users.length;
  return `<div class="search-heading"><div><span class="eyebrow">ПОШУК У СТУДІЇ</span><h1>Знайдено: ${count}</h1></div><button class="text-button" data-action="clear-search">Очистити ${icon('close')}</button></div>${!count?empty('Нічого не знайдено. Спробуйте назву проєкту, завдання або ім’я учасника.'):''}${found.projects.length?`<section class="search-section"><h2>Проєкти</h2><div class="project-grid">${found.projects.map(card).join('')}</div></section>`:''}${found.tasks.length?`<section class="search-section"><h2>Завдання</h2>${taskTable(found.tasks,true)}</section>`:''}${found.takes.length?`<section class="search-section"><h2>Записи</h2>${fileList(found.takes)}</section>`:''}${found.users.length?`<section class="search-section"><h2>Команда</h2><div class="search-people">${found.users.map((u,i)=>`<button data-page="team">${avatar(u,i)}<span><b>${escape(u.name)}</b><small>${escape(roleLabel(u))}</small></span>${icon('arrow')}</button>`).join('')}</div></section>`:''}`;
}
