let lastErrorTasks=[];
const notify=message=>{const el=$('#toast');el.textContent=message;el.setAttribute('popover','manual');el.classList.add('show');try{el.hidePopover();el.showPopover();}catch{}clearTimeout(notify.timer);notify.timer=setTimeout(()=>{el.classList.remove('show');try{el.hidePopover();}catch{}},6000);};
function showError(error){lastErrorTasks=(error.task_ids||[]).filter(id=>state.tasks.some(t=>t.id===id));let d=$('#error-dialog');if(!d){d=document.createElement('dialog');d.id='error-dialog';document.body.append(d);}d.innerHTML=`<h2>Не вдалося виконати дію</h2><p>${escape(error.message||error)}</p><div class="form-actions">${lastErrorTasks.length?'<button class="button" data-action="error-tasks">Подивитися завдання ('+lastErrorTasks.length+')</button>':''}<button class="button primary" data-action="error-close">Зрозуміло</button></div>`;if(!d.open)d.showModal();}
async function api(route,{method='GET',data,raw=false}={}){const r=await fetch('/api'+route,{method,headers:{authorization:`Bearer ${token}`,...(data?{'content-type':'application/json'}:{})},body:data?JSON.stringify(data):undefined});if(!r.ok){let problem;try{problem=await r.json();}catch{}throw Object.assign(new Error(problem?.error||'Не вдалося виконати запит.'),{task_ids:problem?.task_ids||[],status:r.status});}return raw?r:await r.json();}
async function refresh(){if(!demo)state=await api('/state');else persist();normalizeState(state);render();}
async function browserLogin(){
 const response=await fetch('/api/browser-auth'),config=await response.json();
 if(!response.ok)throw new Error(config.error||'Не вдалося підготувати вхід.');
 $('#app').innerHTML=`<div class="app-error"><img src="/assets/mark-red.png" alt="Фомальгаут" style="width:64px"><h2>Вхід у студію</h2><p>Увійдіть через Telegram. Ваші завдання й ролі спільні з Mini App.</p><div id="browser-login-control"></div><p id="browser-login-status" role="status"></p></div>`;
 const control=$('#browser-login-control'),status=$('#browser-login-status');
 if(!config.enabled){status.textContent='Вхід у браузері ще не налаштований адміністратором. Поки відкрийте студію кнопкою в Telegram.';return;}
 if(!window.Telegram?.Login){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://oauth.telegram.org/js/telegram-login.js';script.onload=resolve;script.onerror=()=>reject(new Error('Не вдалося завантажити вхід Telegram. Перевірте блокувальник або з’єднання.'));document.head.append(script);});}
 const button=document.createElement('button');button.className='button primary';button.textContent='Увійти через Telegram';control.append(button);
 window.Telegram.Login.init({client_id:Number(config.client_id),scope:['profile'],nonce:config.nonce},async result=>{
   if(!result?.id_token){status.textContent='Вхід не підтверджено. Спробуйте ще раз.';return;}
   button.disabled=true;status.textContent='Перевіряємо доступ…';
   try{const r=await fetch('/api/browser-auth',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id_token:result.id_token})}),data=await r.json();if(!r.ok)throw new Error(data.error);token=data.token;sessionStorage.setItem('fs-token',token);location.reload();}
   catch(e){status.textContent=e.message;button.textContent='Спробувати знову';button.disabled=false;button.onclick=()=>location.reload();}
 });
 button.onclick=()=>window.Telegram.Login.open();
}
async function init(){
  const tg=window.Telegram?.WebApp;tg?.ready();tg?.expand();
  try{
    let live=false;try{const r=await fetch('/api/health');live=r.ok&&(await r.json()).mode==='live';}catch{}
    if(live){
      if(tg?.initData){const r=await fetch('/api/auth',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({initData:tg.initData})});const data=await r.json();if(!r.ok)throw new Error(data.error);token=data.token;sessionStorage.setItem('fs-token',token);state=data;}
      else {if(token){try{state=await api('/state');}catch(e){if(e.status!==401)throw e;token=null;sessionStorage.removeItem('fs-token');}}if(!state){await browserLogin();return;}}
    }else{
      if(tg?.initData)throw new Error('Цей інтерфейс ще не підключено до серверної частини. Налаштуйте VPS та URL Mini App за інструкцією.');
      demo=true;try{state=JSON.parse(localStorage.getItem('fomalhaut-studio-v1'))||seed();}catch{state=seed();}
    }
    normalizeState(state);if(demo)upgradeDemo(state);
    const openInbox=location.hash==='#/inbox';applyRoute(decodeRoute(location.hash));
    history.replaceState({studio:true,route:currentRoute(),depth:0,scroll:0},'',encodeRoute(currentRoute()));
    if(tg?.initData&&tg.BackButton)tg.BackButton.onClick(goBack);
    render();
    if(!state.profiles?.find(p=>p.user_id===state.user.id)?.timezone){try{await workflow({type:'timezone',data:{zone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Kyiv'}});}catch{}}
    if(!state.profiles?.find(p=>p.user_id===state.user.id)?.onboarding_seen){
      const previouslySeen=localStorage.getItem('studio-onboard:'+state.user.id);
      try{await workflow({type:'onboarding-seen'});localStorage.setItem('studio-onboard:'+state.user.id,'1');if(!previouslySeen)showOnboarding(0);}catch{notify('Не вдалося зберегти налаштування знайомства. Його можна відкрити в акаунті.');}
    }
    if(openInbox)inbox();
    let refreshing=false;
    const idle=()=>!demo&&!pendingUpload&&page!=='settings'&&!document.querySelector('dialog[open], #content form')&&!document.activeElement?.matches('input,textarea,select,[contenteditable]');
    setInterval(async()=>{if(refreshing||pendingUpload)return;refreshing=true;const before=$('#content'),revision=stateRevision;try{const next=await api('/state');if(revision!==stateRevision)return;if(!idle()||before!==$('#content')){state.notifications=next.notifications;updateNoticeBell();return;}state=next;normalizeState(state);render();}catch{}finally{refreshing=false;}},10000);
  }catch(e){$('#app').innerHTML=`<div class="app-error"><h2>Не вдалося відкрити студію</h2><p>${escape(e.message)}</p><button class="button" onclick="location.reload()">Спробувати знову</button></div>`;}
}

function preserveAccount(renderPage){
 const forms=page==='settings'?Array.from(document.querySelectorAll('#content form')):[];
 const snapshot=forms.map(f=>({id:f.id,fields:Array.from(f.elements).filter(e=>e.name&&e.type!=='file').map(e=>({name:e.name,value:e.value,checked:e.checked,focus:e===document.activeElement,start:e.selectionStart,end:e.selectionEnd}))}));
 renderPage();
 for(const f of snapshot){const form=document.getElementById(f.id);if(!form)continue;for(const v of f.fields){const e=form.elements.namedItem(v.name);if(!e)continue;e.value=v.value;if('checked' in e)e.checked=v.checked;if(v.focus){e.focus({preventScroll:true});if(v.start!==null&&v.start!==undefined)try{e.setSelectionRange(v.start,v.end);}catch{}}}}
}
function render(){preserveAccount(renderUnsafe);}
function renderMain(){preserveAccount(renderMainUnsafe);}

function unreadNotices(){return state.notifications.filter(n=>n.user_id===state.user.id&&!n.read_at).length;}
function noticeButton(){const n=unreadNotices();return `<button class="iconbtn notice-bell ${n?'has-unread':''}" data-action="inbox" aria-label="Сповіщення${n?': '+n+' непрочитаних':''}" title="${n?'Непрочитаних: '+n:'Немає непрочитаних сповіщень'}">${icon('bell')}${n?'<span class="notice-dot" aria-hidden="true"></span>':''}</button>`;}
function updateNoticeBell(){const b=document.querySelector('[data-action="inbox"]');if(b)b.outerHTML=noticeButton();}
function renderUnsafe(){
  const nav=[['overview','grid','Головна'],['projects','folder','Проєкти'],['tasks','tasks','Завдання'],['files','file','Матеріали'],['team','users','Команда']];
  if(canAdmin())nav.push(['analytics','grid','Аналітика']);
  const active=page==='project'?'projects':page;
  const count=state.tasks.filter(t=>t.assignee===state.user.id&&['todo','working'].includes(t.status)).length;
  $('#app').innerHTML=`<div class="shell app-shell"><div class="workspace"><header class="topbar app-topbar"><div class="header-leading">${page!=='overview'?`<button class="iconbtn screen-back" data-action="back" aria-label="Назад">${icon('back')}</button>`:''}<a class="app-brand" href="#/overview" data-page="overview" aria-label="Фомальгаут — головна"><img src="/assets/mark-red.png" alt=""><span>ФОМАЛЬГАУТ<small>STUDIO</small></span></a></div><div class="top-actions">${!demo&&!window.Telegram?.WebApp?.initData?'<button class="button small" id="session-logout">Вийти</button>':''}<span class="desktop-role">${escape(roleLabel(state.user))}</span>${transferButton()}${noticeButton()}<button class="profile-button ${page==='settings'?'selected':''}" data-page="settings" aria-label="Профіль і налаштування">${avatar(state.user)}</button></div></header>${demo?`<div class="demo-strip"><button data-action="setup" class="demo-info"><span class="status-dot"></span>Деморежим <span class="demo-explainer">· дані у цьому браузері</span></button><select class="mode-select" id="demo-role" aria-label="Демонстраційна роль">${state.users.filter(u=>u.access==='active'&&!u.id.startsWith('guest:')).map(u=>`<option value="${u.id}" ${state.user.id===u.id?'selected':''}>${escape(u.name)} · ${escape(roleLabel(u))}</option>`).join('')}</select></div>`:''}<div class="global-search"><div class="searchbox">${icon('search')}<input id="search" type="search" aria-label="Пошук проєктів і завдань" placeholder="Знайти проєкт, завдання або файл" value="${escape(search)}"></div></div><main class="content page-${page}" id="content">${mainContent()}</main></div><nav class="bottom-nav" aria-label="Головна навігація">${nav.map(([id,i,label])=>`<button data-page="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon(i)}${id==='tasks'&&count?`<span class="nav-badge">${count>9?'9+':count}</span>`:''}</span><span>${label}</span></button>`).join('')}</nav></div>`;
  syncBack();
}
const heading=(eyebrow,title,subtitle,actions='')=>`<div class="eyebrow">${eyebrow}</div><div class="pagehead"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="head-actions">${actions}</div></div>`;
const newProject=()=>canAdmin()?`<button class="button primary" data-action="new-project">${icon('plus')}Новий проєкт</button>`:'';
const newTask=(pid='')=>canAdmin()?`<button class="button primary" data-action="new-task" data-id="${pid}">${icon('plus')}Нове завдання</button>`:'';
function statCards(){const tasks=visibleTasks();return `<div class="stats">${[['Активні проєкти',state.projects.length,'folder','Простір для кожної історії'],['Завдання у роботі',tasks.filter(t=>['todo','working','revision'].includes(t.status)).length,'mic','Кожен голос має значення'],['На перевірці',tasks.filter(t=>t.status==='review').length,'file','Чекають на звукорежисера'],['Затверджені записи',tasks.filter(t=>t.status==='approved').length,'check','<strong>Готові до зведення</strong>']].map(([label,n,i,sub])=>`<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${String(n).padStart(2,'0')}</div><div class="stat-bottom">${sub}</div></div>`).join('')}</div>`;}
function card(p,index){const tasks=state.tasks.filter(t=>!t.material_kind&&t.project_id===p.id),done=tasks.filter(t=>t.status==='approved').length,progress=tasks.length?Math.round(done/tasks.length*100):0;const members=[...new Set(tasks.map(t=>t.assignee))].map(user);const due=tasks.filter(t=>!['approved','review'].includes(t.status)).sort((a,b)=>a.deadline.localeCompare(b.deadline))[0];return `<article class="project-card" data-project-card="${p.id}"><div class="project-top"><div class="project-art art${index%3}"><span>${escape(p.code.slice(0,2).toUpperCase())}</span><img src="/assets/orbit-grey.png" alt=""></div><div><button class="project-title" data-project="${p.id}">${escape(p.title)}</button><span class="paid-label">${p.paid?'Оплачуваний · вищий пріоритет':'Неоплачуваний'}</span><div class="project-meta"><span>${p.episode_count||new Set(tasks.map(t=>t.episode)).size} серій</span><span>·</span><span>${members.length} учасників</span></div></div>${badge(progress===100&&tasks.length?'approved':'working')}</div><div class="project-progress"><span>Завдання проєкту</span><b>${done} / ${tasks.length} &nbsp; · &nbsp; ${progress}%</b></div><div class="progress-track"><i style="width:${progress}%"></i></div><div class="project-bottom"><div class="avatars">${members.map(avatar).join('')}</div><span class="due ${due&&Date.parse(due.deadline)<Date.now()?'overdue':''}">${icon('clock')}${due?'Найближчий дедлайн: '+when(due.deadline,due.assignee):'Усе за планом'}</span><button class="rowbtn" data-project="${p.id}" aria-label="Відкрити ${escape(p.title)}">${icon('arrow')}</button></div></article>`;}
const filteredProjects=()=>state.projects.filter(p=>p.id!=='general').filter(p=>!search||p.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(b.paid||0)-(a.paid||0));
const ROLE_ACTIONS={translator:['Здати переклад','translation'],editor:['Здати редактуру','editing'],casting:['Роздати субтитри','casting'],actor:['Записи та правки','recording,correction'],reviewer:['Вислухати записи','review'],engineer:['Працювати над зведенням','mixing']};
function overview(){
 const mine=state.tasks.filter(t=>t.assignee===state.user.id),pending=mine.filter(t=>['todo','working','revision'].includes(t.status)).sort((a,b)=>priorityCompare(state,a,b));
 const overdue=pending.filter(t=>Date.parse(t.deadline)<Date.now()).length,done=mine.filter(t=>t.status==='approved').length;
 const actions=roles(state.user).filter(r=>ROLE_ACTIONS[r]).map(r=>{const [label,stages]=ROLE_ACTIONS[r];const count=pending.filter(t=>stages.split(',').includes(t.stage)).length;return `<button data-action="role-tasks" data-stages="${stages}">${icon(r==='actor'?'mic':'tasks')}<span>${label}<small>Моїх завдань: ${count}</small></span></button>`;}).join('');
 return `<div class="home-greeting"><div><p>${escape(new Date().toLocaleDateString('uk-UA',{weekday:'long',day:'numeric',month:'long'}))}</p><h1>Привіт, ${escape(state.user.name.split(' ')[0])}<span class="greeting-dot">.</span></h1></div><span class="home-role">${escape(roleLabel(state.user))}</span></div><section class="focus-card"><div class="focus-copy"><span class="focus-label">МІЙ РОБОЧИЙ ДЕНЬ</span><h2>${pending.length?'Наступний крок<br>до готової серії.':'Усе здано.<br>Можна видихнути.'}</h2><button class="focus-link" data-page="tasks" data-filter="mine">Мої активні завдання: ${pending.length} ${icon('arrow')}</button></div><img src="/assets/orbit-red.png" alt="" class="focus-orbit"></section><div class="home-stats"><button data-page="tasks" data-filter="mine"><span>${icon('tasks')}Мої активні</span><b>${pending.length}</b></button><button data-action="my-overdue"><span>${icon('clock')}Прострочено</span><b class="red-number">${overdue}</b></button><button data-action="my-done"><span>${icon('check')}Завершено мною</span><b>${done}</b></button></div><div class="quick-actions">${actions}${canAdmin()?`<button data-action="new-task">${icon('plus')}<span>Створити завдання</span></button><button data-page="deadlines">${icon('clock')}<span>Дедлайни команди</span></button><button data-page="team">${icon('users')}<span>Керувати командою</span></button>`:''}<button data-page="files">${icon('file')}<span>Усі матеріали</span></button></div><section class="home-tasks"><div class="section-head"><h2>Мої наступні завдання</h2><button class="text-button" data-page="tasks" data-filter="mine">Усі ${icon('arrow')}</button></div><p class="subtitle">Найближчі дати — першими. За однакової дати оплачувані завдання мають пріоритет.</p>${taskTable(pending.slice(0,6))}</section>${canAdmin()?`<section class="home-tasks"><div class="section-head"><h2>Потребує уваги команди</h2><button class="text-button" data-page="tasks" data-filter="all">Усі завдання</button></div>${taskTable(visibleTasks().filter(t=>t.status!=='approved').sort((a,b)=>priorityCompare(state,a,b)).slice(0,4))}</section>`:''}`;
}

function projectsPage(){return heading('КОМАНДНИЙ ПРОСТІР','Проєкти','Усі історії, над якими працюємо разом.',newProject())+`<div class="project-grid">${filteredProjects().map(card).join('')||empty('Проєктів поки немає.')}</div>`;}
function taskTable(tasks,alreadyFiltered=false,overdue=false){
  tasks=tasks.filter(t=>!t.material_kind&&t.status!=='planned').sort((a,b)=>priorityCompare(state,a,b,overdue));
  if(!alreadyFiltered)tasks=tasks.filter(t=>!search||`${t.character} ${project(t.project_id)?.title} ${user(t.assignee)?.name}`.toLowerCase().includes(search.toLowerCase()));
  return tasks.length?`<div class="task-list">${tasks.map(t=>{const late=Date.parse(t.deadline)<Date.now()&&!['approved','review'].includes(t.status);return `<button class="task-card ${late?'task-late':''}" data-action="task-detail" data-id="${t.id}"><span class="task-card-top"><span class="task-project">${escape(project(t.project_id)?.title)} <i>·</i> ${t.project_id==='general'?'Без проєкту':String(t.episode).padStart(2,'0')+' серія'}</span>${icon('arrow')}</span><span class="task-stage">${STAGES[t.stage]||'Запис'}${project(t.project_id)?.paid?' · ОПЛАЧУВАНИЙ':''}</span><span class="task-card-title">${escape(taskLabel(t))}</span><span class="task-card-middle">${badge(t.status)}<span class="task-deadline ${late?'overdue':''}">${icon('clock')}${late?'Дедлайн минув · ':''}${when(t.deadline,t.assignee)}</span></span><span class="task-card-bottom"><span class="person">${avatar(user(t.assignee),state.users.indexOf(user(t.assignee)))}${escape(user(t.assignee)?.name)}</span><span class="task-open">Відкрити завдання</span></span></button>`;}).join('')}</div>`:empty('Завдань за цим фільтром немає.');
}
function taskVisibility(){return `<label class="task-visibility"><input type="checkbox" id="show-others" ${showOthers?'checked':''}> Показувати чужі завдання</label>`;}
function tasksPage(){let tasks=visibleTasks().filter(t=>showOthers||t.assignee===state.user.id);if(filter!=='all')tasks=tasks.filter(t=>filter==='mine'?t.assignee===state.user.id&&t.status!=='approved':filter==='overdue'?t.status!=='approved'&&Date.parse(t.deadline)<Date.now():t.status===filter);return heading('РОБОТА КОМАНДИ','Завдання','Спочатку найближчі дати; за однакової дати — оплачувані. У прострочених — спочатку оплачувані.',(canAdmin()?'<button class="button" data-page="deadlines">Дедлайни</button>':'')+newTask())+`<div class="filters">${taskVisibility()}<select id="status-filter" aria-label="Фільтр статусу">${[['all','Усі статуси'],['mine','Призначені мені'],['overdue','Прострочені'],...Object.entries(statusNames).filter(([k])=>k!=='planned')].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div>`+taskTable(tasks,false,filter==='overdue');}
function projectPage(){
 const p=project(selectedProject);if(!p)return projectsPage();
 const ts=state.tasks.filter(t=>t.project_id===p.id&&t.status!=='planned'),eps=state.episodes.filter(e=>e.project_id===p.id);
 const legacy=[...new Set(ts.filter(t=>!eps.some(e=>e.number===t.episode)).map(t=>t.episode))];
 const actions=canAdmin()?`<button class="button" data-action="edit-project" data-id="${p.id}">Редагувати</button><button class="button" data-action="members" data-id="${p.id}">Команда</button><button class="button" data-action="bind" data-id="${p.id}">${icon('link')}Гілка</button><button class="button primary" data-action="new-episode" data-id="${p.id}">+ Серія</button><button class="button" data-action="import-progress" data-id="${p.id}">Перенести прогрес</button>`:'';
 return heading(p.paid?'ОПЛАЧУВАНИЙ · ВИЩИЙ ПРІОРИТЕТ':'НЕОПЛАЧУВАНИЙ ПРОЄКТ',escape(p.title),escape(p.description),actions)+`<div class="member-strip">${state.memberships.filter(m=>m.project_id===p.id).map(m=>`<span>${escape(ROLES[m.role])}: <b>${escape(user(m.user_id)?.name)}</b></span>`).join('')||'Адміністратор ще не призначив команду.'}</div><div class="tabs">${[['tasks','Завдання'],['files','Усі файли'],['episodes','Виробництво']].map(([v,t])=>`<button class="${projectTab===v?'active':''}" data-tab="${v}">${t}</button>`).join('')}</div>${projectTab==='tasks'?taskVisibility()+taskTable(ts.filter(t=>showOthers||t.assignee===state.user.id)):projectTab==='files'?projectFiles(p.id):`<div class="episode-grid">${[...eps,...legacy.map(number=>({number,legacy:true}))].sort((a,b)=>a.number-b.number).map(e=>e.legacy?((n)=>`<section class="episode"><span class="eyebrow">ПОПЕРЕДНІ ЗАПИСИ</span><h2>Серія ${n}</h2><p>Історію збережено. Завдання створені до виробничого процесу.</p>${progressButton(p.id,n)}${materialButton(p.id,n)}<button class="button" data-action="episode-tasks" data-episode="${n}">Завдання</button>${roles(state.user).some(r=>['engineer','admin'].includes(r))?`<button class="button" data-action="zip" data-id="${p.id}" data-episode="${n}">ZIP наявних записів</button>`:''}</section>`)(e.number):episodeCard(e)).join('')}</div>`}`;
}
function progressButton(pid,number){return `<button class="button" data-action="episode-progress" data-id="${escape(pid)}" data-episode="${number}">Прогрес серії</button>`;}
function showEpisodeProgress(pid,number){
 const rows=episodeProgress(state,pid,number),late=rows.flatMap(r=>r.late);
 modal(`${escape(project(pid)?.title)} · Серія ${number}`,`<p class="modal-sub">Прогрес за етапами та виконавцями. Здані записи очікують перевірки й не вважаються простроченою роботою актора.</p>${late.length?`<p class="notice overdue">Прострочених завдань: ${late.length}. ${escape([...new Set(late.map(t=>user(t.assignee)?.name||'Не призначено'))].join(', '))}</p>`:'<p class="notice">Прострочених активних завдань немає.</p>'}<div class="episode-progress">${rows.map(r=>`<section class="progress-stage"><div class="split"><h3>${STAGES[r.stage]}</h3><span>${r.done} / ${r.tasks.length} завершено</span></div>${r.manual?'<p class="notice">Очікує ручного дозволу адміністратора.</p>':''}${r.missing?'<p class="notice overdue">Потрібно призначити виконавця.</p>':''}${r.tasks.length?r.tasks.map(t=>`<div class="progress-person ${r.late.includes(t)?'progress-late':''}"><div><strong>${escape(user(t.assignee)?.name||'Не призначено')}</strong>${t.stage==='correction'?` · FIX${(t.fix_iteration||1)>1?t.fix_iteration:''}`:''}<div>${t.admin_closed?'Закрито адміністратором без виконання':badge(t.status)}${r.late.includes(t)?' <b class="overdue">Дедлайн минув</b>':''}</div><small>${t.status==='planned'?'Етап ще не запущено':t.deadline?escape(zonedDate(t.deadline,userZone(state,t.assignee))):'Дедлайн ще не встановлено'}</small>${t.status==='review'?'<small>Матеріали здано — очікують перевірки.</small>':''}</div>${t.status!=='planned'?`<button class="button" data-action="task-detail" data-id="${escape(t.id)}">Завдання</button>`:''}</div>`).join(''):`<p class="muted">${r.stage==='correction'?'Завдань на запис правок немає.':'Завдання ще не створено.'}</p>`}</section>`).join('')}</div>`);
}
function episodeCard(e){const ts=state.tasks.filter(t=>t.project_id===e.project_id&&t.episode===e.number),recordings=ts.filter(t=>t.stage==='recording'),done=recordings.filter(t=>['review','approved'].includes(t.status)).length;const stage=e.stage==='planned'?'Заплановано':e.stage==='done'?'Серію завершено':e.stage==='imported'?'Прогрес перенесено':e.stage.startsWith('waiting:')?'Потрібен виконавець: '+STAGES[e.stage.slice(8)]:STAGES[e.stage];return `<section class="episode workflow-episode"><div class="split"><span class="eyebrow">СЕРІЯ ${String(e.number).padStart(2,'0')}</span><span class="badge ${e.stage==='done'?'approved':'working'}">${escape(stage)}</span></div>${e.pendingStages?.length?`<p class="notice">Очікує дозволу адміна: ${e.pendingStages.map(k=>STAGES[k]).join(', ')}</p>`:''}<div class="stage-track">${Object.entries(STAGES).filter(([key])=>key!=='other').map(([key,name])=>`<span class="${ts.some(t=>t.stage===key)?ts.filter(t=>t.stage===key).every(t=>t.status==='approved')?'finished':'current':''}">${name}</span>`).join('')}</div><p>${done} / ${recordings.length} перших записів · ${ts.filter(t=>t.stage==='correction'&&t.status!=='approved').length} правок очікується</p><div class="progress-track"><i style="width:${recordings.length?done/recordings.length*100:0}%"></i></div><div class="episode-actions">${progressButton(e.project_id,e.number)}${materialButton(e.project_id,e.number)}${canAdmin()?`<button class="button primary" data-action="launch-episode" data-id="${e.id}">Список етапів і запуск</button>`:`<button class="button" data-action="episode-tasks" data-episode="${e.number}">Завдання серії</button>`}${roles(state.user).some(r=>['engineer','admin'].includes(r))?`<button class="button" data-action="zip" data-id="${e.project_id}" data-episode="${e.number}" ${done?'':'disabled'}>ZIP наявних записів</button>`:''}${ts.some(t=>t.stage==='casting'&&['todo','working'].includes(t.status)&&(canAdmin()||t.assignee===state.user.id))?`<button class="button" data-action="cast" data-id="${e.id}">Розподіл субтитрів</button>`:''}</div>${e.ready_notified?'<small class="ready-note">Усі записи та правки здано — можна завершувати зведення.</small>':'<small>Звукорежисер може працювати з першими записами.</small>'}</section>`;}
function fileList(takes){return takes.length?'<button class="button" data-action="materials-zip">Завантажити обрані ZIP</button>'+takes.map(t=>{const task=state.tasks.find(a=>a.id===t.task_id);const latest=Math.max(...state.takes.filter(v=>v.task_id===t.task_id).map(v=>v.version))===t.version;return `<article class="file-card"><input type="checkbox" data-material-file value="${t.id}" aria-label="Обрати ${escape(t.filename)}"><span class="file-icon">${icon('file')}</span><div class="file-info"><h3>${t.message_id?`<a href="${telegramUrl(t)}" target="_blank" rel="noopener">${escape(t.filename)}</a>`:escape(t.filename)}</h3>${t.metadata?.uploaded_by?`<small>Виконавець: ${escape(user(t.actor_id||t.metadata.performer_id)?.name||'—')} · Завантажив: ${escape(user(t.metadata.uploaded_by)?.name||'—')}</small>`:''}<p>${bytes(t.bytes)} · ${t.local?'Локальний файл':t.metadata?.kind==='document'?'Матеріал етапу':t.demo?'Приклад запису':`${t.metadata?.sampleRate||'?'} Hz · ${t.metadata?.bits||'?'}-bit · ${t.metadata?.channels||'?'} канал(и)`} · v${t.version} ${state.takes.some(x=>x.metadata?.replaces===t.id)?'· замінений файл':'· актуальний файл'}</p><p>${escape(user(t.actor_id||task?.assignee)?.name)} · ${when(t.created_at)}</p></div><div class="actions"><button class="button small" data-action="download-take" data-id="${t.id}">Скачати</button>${t.message_id?`<a class="button small" href="${telegramUrl(t)}" target="_blank" rel="noopener">${icon('send')}Telegram</a>`:''}${canRequestFix()&&['recording','correction'].includes(task?.stage)&&!t.local?`<button class="button small" data-action="request-fix" data-id="${task.id}" data-take="${t.id}">${icon('check')}Запросити правки</button>`:''}${task&&(canAdmin()||(task.material_kind?(task.material_editors||[task.assignee]).includes(state.user.id):task.assignee===state.user.id))?`<button class="button small danger" data-action="remove-take-preview" data-id="${t.id}">Вилучити</button>`:''}${t.local?'<span class="badge local">Не опубліковано</span>':''}</div></article>`;}).join(''):empty('Ще немає записів. Відкрийте завдання, щоб здати файл.');}
function telegramUrl(t){const channel=String(t.chat_id).replace(/^-100/,'');return `https://t.me/c/${channel}/${Number(t.thread_id)}/${Number(t.message_id)}`;}
let materialsProject='all',materialsPerson='all',materialsSort='new';
function filesPage(){const tasks=new Map(state.tasks.map(t=>[t.id,t]));const takes=state.takes.filter(v=>(materialsProject==='all'||tasks.get(v.task_id)?.project_id===materialsProject)&&(materialsPerson==='all'||(v.actor_id||v.metadata?.performer_id||tasks.get(v.task_id)?.assignee)===materialsPerson)).sort((a,b)=>materialsSort==='name'?a.filename.localeCompare(b.filename):materialsSort==='size'?b.bytes-a.bytes:materialsSort==='old'?a.created_at.localeCompare(b.created_at):b.created_at.localeCompare(a.created_at));return heading('ФАЙЛИ КОМАНДИ','Матеріали','Усі версії, включно із заміненими файлами.')+`<div class="filters"><label>Проєкт<select id="materials-project"><option value="all">Усі проєкти</option>${options(state.projects,materialsProject)}</select></label><label>Виконавець<select id="materials-person"><option value="all">Усі виконавці</option>${options(state.users,materialsPerson,'name')}</select></label><label>Сортування<select id="materials-sort">${[['new','Спочатку нові'],['old','Спочатку старі'],['name','За назвою'],['size','За розміром']].map(([v,n])=>`<option value="${v}" ${v===materialsSort?'selected':''}>${n}</option>`).join('')}</select></label></div><p>${takes.length} файлів</p>`+fileList(takes);}

function teamPage(){return heading('ЛЮДИ СТУДІЇ','Команда','Кілька ролей для однієї людини. Усі активні учасники мають доступ до всіх файлів.')+`${accessQueue()}${canAdmin()?'<button class="button primary" data-action="new-guest">Додати гостя</button>':''}<div class="team-grid">${state.users.map((u,i)=>`<article class="person-card">${avatar(u,i)}<h2>${escape(u.name)}</h2><p>${escape(u.id.startsWith('guest:')?'Гість · керує адміністратор':u.username?'@'+u.username:u.id)}</p><div class="role-chips">${roles(u).map(r=>`<span>${ROLES[r]}</span>`).join('')}</div><p class="access-${u.access}">${{active:'Доступ надано',pending:'Очікує доступу',blocked:'Заблоковано'}[u.access]}</p>${canAdmin()?`<button class="button" data-action="edit-user" data-id="${u.id}">Ролі та доступ</button>`:''}</article>`).join('')}</div>`;}
function settingsPage(){return heading('ТВІЙ РОБОЧИЙ ПРОСТІР','Налаштування','Менше ручної роботи. Більше часу на озвучення.')+`<button class="button primary" data-action="onboarding">Пройти знайомство з програмою</button><form id="profile-form" class="aside-card">${field('Мій нік',`<input name="name" value="${escape(state.user.name)}" maxlength="80" required>`)}${formEnd('Зберегти нік')}<button type="button" class="button" data-action="sync-avatar">Оновити аватарку з Telegram</button></form>${timezoneForm()}${birthdayForm()}<div class="settings-grid">${canAdmin()?`<section class="aside-card"><h2>Telegram і гілки</h2><p class="subtitle" style="margin-top:12px">Прив’язка окремої гілки до кожного проєкту.</p>${state.projects.map(p=>`<div class="split" style="margin-top:20px;font-size:13px"><span>${escape(p.title)}<small style="display:block;margin-top:5px;color:#737373">${p.thread_id?'Гілка #'+p.thread_id+(demo?' · локальна прив’язка':''):'Ще не прив’язано'}</small></span><button class="button small" data-action="bind" data-id="${p.id}">${icon('link')}Змінити</button></div>`).join('')}</section>`:''}<section class="aside-card"><h2>Особисті сповіщення</h2>${reminderForm()}<p class="subtitle" style="margin-top:12px">Передавання етапів, нові записи, правки та нагадування про дедлайн — відповідальним особисто.</p><div class="notice">Telegram попросить дозвіл на повідомлення. Вони надходитимуть у приватний діалог із ботом; приховати цей діалог технічно неможливо.</div><button class="button primary" data-action="notifications">${icon('bell')}${state.user.notify?'Вимкнути нагадування':'Увімкнути нагадування'}</button></section>${canAdmin()?`<section class="aside-card"><h2>${demo?'Підключення студії':'Стан сервісу'}</h2><p class="subtitle" style="margin-top:12px">${demo?'Це інтерактивна демонстрація з прикладами. Серверний код готовий до налаштування на VPS.':'Вхід через Telegram. Файли після обробки зберігаються у гілках вашої групи.'}</p><button class="button" style="margin-top:20px" data-action="setup">${icon('settings')}Як підключити</button>${demo?'<button class="button danger" style="margin-top:20px" data-action="reset">Скинути демодані</button>':''}</section>`:''}</div>${state.notificationErrors?.length?`<div class="notice warn">Не доставлено ${state.notificationErrors.length} сповіщень. Перевірте, чи учасники дозволили боту писати, та журнали сервера.</div>`:''}`;}
function empty(label){return `<div class="empty">${icon('folder')}${label}</div>`;}
function modal(title,content,subtitle=''){modalRevision++;inTaskView=false;const d=$('#modal');if(!history.state?.sheet){rememberRoute();history.pushState({...history.state,sheet:true,depth:(history.state?.depth||0)+1},'',encodeRoute(currentRoute()));}d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="iconbtn" data-close aria-label="Закрити">${icon('close')}</button></div>${subtitle?`<p class="modal-sub">${subtitle}</p>`:''}${content}`;if(!d.open)d.showModal();document.documentElement.classList.add('sheet-open');d.scrollTop=0;d.querySelector('[data-close]')?.focus({preventScroll:true});syncBack();}
const field=(label,content)=>`<label class="field">${label}${content}</label>`;
const options=(items,selected,label='title')=>items.map(i=>`<option value="${escape(i.id)}" ${i.id===selected?'selected':''}>${escape(i[label])}</option>`).join('');
const formEnd=(label='Зберегти')=>`<div class="form-error" id="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button" data-close>Скасувати</button><button class="button primary" type="submit">${label}</button></div></form>`;
function paidField(value){return field('Оплата проєкту',`<select name="paid"><option value="0" ${!value?'selected':''}>Неоплачуваний</option><option value="1" ${value?'selected':''}>Оплачуваний — вищий пріоритет</option></select>`);}
function projectModal(){modal('Новий проєкт',`<form id="project-form">${field('Назва проєкту','<input name="title" placeholder="Наприклад, Мадока Маґіка" maxlength="100" required>')}${field('Код для назв файлів','<input name="code" placeholder="Madoka" pattern="[A-Za-z0-9_-]+" maxlength="30" required><small>Латинські літери, цифри, _ та -. Наприклад: Nick_S01E03_Madoka_VO.flac</small>')}${field('Короткий опис','<textarea name="description" placeholder="Сезон, примітки для команди…" maxlength="500"></textarea>')}${field('Сезон','<input name="season" type="number" min="1" max="999" value="1" required>')}${field('Кількість серій','<input name="episode_count" type="number" min="1" max="9999" value="1" required>')}${paidField(0)}${formEnd('Створити проєкт')}`);}
function taskModal(pid){if(!state.projects.length)return notify('Спершу створіть проєкт.');modal('Нове завдання',`<form id="task-form">${field('Напрямок',`<select name="stage" id="task-stage">${Object.entries(STAGES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select>`)}${field('Проєкт',`<select name="project_id" id="task-project">${options([...state.projects].sort((a,b)=>(b.id==='general')-(a.id==='general')),pid||'general')}</select>`)}${field('Серія','<input name="episode" type="number" min="1" max="9999" value="1" required>')}${field('Назва завдання','<input name="character" maxlength="80" placeholder="Що потрібно зробити?" required>')}${field('Виконавець','<select name="assignee" id="task-assignee" required></select>')}${field('Дедлайн',`<input name="deadline" type="datetime-local"><small>Час введення — за поясом обраного виконавця (Налаштування акаунта; типово Київ). Залиште порожнім для стандартного строку напрямку.</small>`)}${field('Опис','<textarea name="note" maxlength="2000" placeholder="Опишіть результат, який очікується"></textarea>')}<p class="notice">Окреме завдання: не перемикає автоматичні етапи серії.</p>${formEnd('Призначити завдання')}</form>`);updateTaskPeople();updateGeneralTask();}
function updateGeneralTask(){const input=$('#task-form [name=episode]');if(input)input.closest('label').hidden=$('#task-project').value==='general';}
document.addEventListener('change',e=>{if(e.target.id==='task-project')updateGeneralTask();});
function updateTaskPeople(){const stage=$('#task-stage').value;$('#task-assignee').innerHTML=options(state.users.filter(u=>u.access==='active'&&(stage==='other'||roles(u).includes(STAGE_ROLE[stage]))),null,'name');}

function bindingModal(pid){if(!canAdmin())return;const p=project(pid)||state.projects[0];modal('Прив’язати гілку',`<form id="binding-form">${field('Проєкт',`<select name="project_id">${options(state.projects,p.id)}</select>`)}${field('Посилання на гілку',`<input name="link" value="${escape(p.link||'')}" placeholder="https://t.me/c/1234567890/42" required><small>Скопіюйте посилання на саму тему (гілку) через її меню. Не посилання на звичайне повідомлення.</small>`)}<div id="binding-preview"></div><button class="button" type="button" data-action="parse-link">Визначити гілку</button>${formEnd('Зберегти прив’язку')}`);}
async function parseBinding(){const b=Object.fromEntries(new FormData($('#binding-form')));const r=demo?parseTelegramTopicLink(b.link):await api('/resolve-link',{method:'POST',data:b});$('#binding-preview').innerHTML=`<p>Група: ${escape(r.chatTitle||r.chatId)} · Гілка: ${r.threadId}</p>`;return r;}
const canRequestFix=()=>roles(state.user).some(r=>['admin','reviewer','engineer'].includes(r));
function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(t)productionTask(t);}

function uploadModal(id){const task=state.tasks.find(t=>t.id===id),isAudio=['recording','correction'].includes(task.stage),subs=['translation','editing','casting'].includes(task.stage);modal(isAudio?'Надіслати записи':'Надіслати матеріали',`<form id="upload-form" data-id="${id}">${field('Дія з файлами',`<select name="replaces"><option value="">Додати файли</option>${state.takes.filter(v=>v.task_id===id&&!v.local&&!state.takes.some(x=>x.metadata?.replaces===v.id)).map(v=>`<option value="${v.id}">Замінити ${escape(v.filename)}</option>`).join('')}</select>`)}<p>Виконавець: ${escape(user(task.assignee)?.name)}</p><label class="dropzone">${icon('upload')}<b>Оберіть файли</b><small>${subs?'Субтитри або ZIP':isAudio?'WAV або FLAC':'Матеріали етапу'} · до 2000 МБ кожен</small><input name="audio" type="file" multiple accept="${subs?SUBTITLE_EXTENSIONS.join(','):isAudio?'.flac,.wav':[...SUBTITLE_EXTENSIONS,'.flac','.wav','.mp4','.mkv'].join(',')}" required></label><div id="selected-audio" class="selected-audio" hidden></div><div class="notice">${demo?'Деморежим: надсилання імітується у цьому браузері; Telegram не підключено.':'Після натискання файли одразу надсилаються на обробку й у гілку проєкту.'}</div><progress id="upload-progress" value="0" max="100" hidden></progress><div id="upload-status" role="status"></div>${formEnd('Надіслати файли')}`);}

function reviewModal(id){const t=state.tasks.find(t=>t.id===id);modal('Перевірка запису',`<p class="subtitle">${escape(taskLabel(t))} · ${escape(project(t.project_id).title)}</p><div class="notice">Затверджений запис потрапить до ZIP серії. Автоматична технічна перевірка не оцінює дикцію, шум і якість виконання.</div><div class="form-actions"><button class="button" data-action="revision" data-id="${id}">На перезапис</button><button class="button primary" data-action="approved" data-id="${id}">${icon('check')}Затвердити</button></div>`);}
async function changeStatus(id,status){if(demo){state.tasks.find(t=>t.id===id).status=status;}else await api('/tasks/'+id,{method:'PATCH',data:{status}});closeSheet();await refresh();notify(status==='approved'?'Запис затверджено':status==='revision'?'Повернуто на перезапис':'Завдання взято в роботу');}
function setupModal(){modal('Підключення до Telegram',`<div class="notice">${demo?'Ця сторінка — приватна демонстрація інтерфейсу. Для всієї команди запустіть серверний пакет на своєму HTTPS-домені.':'Інтерфейс уже підключено до сервера.'}</div><ol class="checklist"><li>Створіть бота в @BotFather.</li><li>Додайте бота адміністратором групи з гілками.</li><li>На VPS заповніть .env: токен, ID групи, ID двох адмінів, API ID / hash Telegram.</li><li>Запустіть Docker Compose з Local Bot API та FFmpeg.</li><li>Вкажіть домен у Main Mini App через BotFather.</li><li>Закріпіть посилання на Mini App у групі.</li></ol><p class="subtitle">Точні команди, налаштування домену й перевірки є у README_UK.md серверного пакета. Токен бота вводиться лише на VPS.</p>${demo?'<a class="button primary" style="margin-top:20px" href="/Fomalhaut-Studio.zip" download>Завантажити серверний пакет</a>':''}`);}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button,a');if(!b){const card=e.target.closest('[data-project-card]');if(card&&!e.target.closest('input,select,audio'))navigate({page:'project',projectId:card.dataset.projectCard});return;}
  if(b.hasAttribute('data-close')){closeSheet();return;}
  if(b.dataset.page){e.preventDefault();navigate({page:b.dataset.page,filter:b.dataset.filter||(b.dataset.page==='tasks'&&!canAdmin()?'mine':'all')});return;}
  if(b.dataset.project){navigate({page:'project',projectId:b.dataset.project});return;}
  if(b.dataset.tab){projectTab=b.dataset.tab;rememberRoute();renderMain();return;}
  const action=b.dataset.action,id=b.dataset.id;if(!action)return;
  try{
    if(action==='onboarding')showOnboarding(Number(b.dataset.step||0));
    if(action==='onboarding-done'){localStorage.setItem('studio-onboard:'+state.user.id,'1');closeSheet();}
    if(action==='new-guest')modal('Новий гість',`<form id="guest-form"><label>Ім’я або псевдонім<input name="name" required maxlength="80"></label><p>Гість не має входу. Додайте його до команди проєкту та призначте роль; файли здає адмін через завдання гостя.</p>${formEnd('Створити гостя')}</form>`);
    if(action==='batch-all'){b.closest('fieldset').querySelectorAll('[name=recipient]').forEach(x=>x.checked=true);}
    if(action==='batch-none'){b.closest('fieldset').querySelectorAll('[name=recipient]').forEach(x=>x.checked=false);}
    if(action==='batch-subs')batchModal(id);
    if(action==='role-tasks'){const stages=b.dataset.stages.split(',');modal('Мої завдання',taskTable(state.tasks.filter(t=>t.assignee===state.user.id&&['todo','working'].includes(t.status)&&stages.includes(t.stage))));}
    if(action==='my-overdue')modal('Мої прострочені завдання',taskTable(state.tasks.filter(t=>t.assignee===state.user.id&&['todo','working'].includes(t.status)&&Date.parse(t.deadline)<Date.now()),false,true));
    if(action==='my-done')modal('Завершено мною',taskTable(state.tasks.filter(t=>t.assignee===state.user.id&&t.status==='approved')));
    if(['bind','setup','new-project'].includes(action)&&!canAdmin())throw new Error('Доступно лише адміністратору.');
    if(action==='sync-avatar'){if(demo)notify('У демо немає Telegram-профілю. Синхронізація працює на підключеному сервері.');else{await api('/profile/avatar',{method:'POST',data:{}});await refresh();notify('Аватарку оновлено');}}
    if(action==='deadline-table'||action==='deadline-calendar'){deadlineView=action==='deadline-table'?'table':'calendar';renderMain();}
    if(action==='calendar-prev'||action==='calendar-next'){deadlineMonth.setMonth(deadlineMonth.getMonth()+(action==='calendar-prev'?-1:1));renderMain();}
    if(action==='back')goBack();
    if(action==='clear-search'){search='';rememberRoute();$('#search').value='';renderMain();$('#search').focus();}
    if(action==='new-project')projectModal();
    if(action==='choose-upload'){const ts=visibleTasks().filter(t=>t.assignee===state.user.id&&['todo','working'].includes(t.status));modal('Для якого завдання?',ts.length?`<div class="upload-choices">${ts.map(t=>`<button class="upload-choice" data-action="upload" data-id="${t.id}"><span><b>${escape(taskLabel(t))}</b><small>${escape(project(t.project_id)?.title)} · ${t.episode} серія</small></span>${icon('upload')}</button>`).join('')}</div>`:empty('У вас поки немає призначених завдань.'));}
    if(action==='new-task')taskModal(id);
    if(action==='bind')bindingModal(id);
    if(action==='parse-link')await parseBinding();

    if(action==='error-close')$('#error-dialog').close();
    if(action==='error-tasks'){$('#error-dialog').close();modal('Завдання, що потребують уваги',taskTable(state.tasks.filter(t=>lastErrorTasks.includes(t.id))));}
    if(action==='attach-files')attachModal(id);
    if(action==='resolve-files')await resolveAttached(id);
    if(action==='attach-manual')manualAttach(id);
    if(action==='manual-preview')manualAttachPreview(id);
    if(action==='batch-preview')previewBatch();
    if(action==='batch-back')renderBatchMapping();
    if(action==='batch-send')await sendBatch(b);
    if(action==='review-downloads')reviewDownloads(id);
    if(action==='review-select-all'||action==='review-select-none')document.querySelectorAll('[data-review-download]:not(:disabled)').forEach(x=>x.checked=action==='review-select-all');
    if(action==='review-edit'){await workflow({type:'review-reopen',task_id:id,data:{user_id:b.dataset.user}});await finishTaskAction();}
    if(action==='review-preview')previewReview(id);
    if(action==='review-back')productionTask(state.tasks.find(t=>t.id===id));
    if(action==='review-send'){if(!reviewPreview||reviewPreview.task_id!==id)throw new Error('Повторіть попередній перегляд.');b.disabled=true;try{await workflow({type:'review-notify',task_id:id,data:{entries:reviewPreview.entries}});reviewDrafts.delete(id);for(const key of notionDrafts.keys())if(key.startsWith(id+':'))notionDrafts.delete(key);reviewPreview=null;await finishTaskAction();notify('Акторів сповіщено');}finally{b.disabled=false;}}
    if(action==='download-take'){const file=state.takes.find(v=>v.id===id);if(demo){const local=localFiles.get(id)||(file.demo_content?{url:URL.createObjectURL(new Blob([file.demo_content],{type:'text/plain'}))}:null);if(local){const a=document.createElement('a');a.href=local.url;a.download=file.filename;a.click();}else notify('Це приклад. Справжні субтитри завантажуються на підключеному сервері.');}else{b.disabled=true;try{await downloadBlob('/takes/'+id+'/download',file.filename);}finally{b.disabled=false;}}}
    if(action==='review-zip'){const t=state.tasks.find(t=>t.id===id);const ids=b.dataset.all?[]:[...document.querySelectorAll('[data-review-download]:checked')].map(x=>x.value);if(!b.dataset.all&&!ids.length)throw new Error('Оберіть акторів для архіву.');if(demo)notify('ZIP доступний на підключеному сервері; демозаписи не містять аудіо.');else{b.disabled=true;try{await downloadBlob(`/projects/${t.project_id}/episodes/${t.episode}/archive?mode=review`+ids.map(x=>'&actor='+encodeURIComponent(x)).join(''),'Записи_для_перевірки.zip');}finally{b.disabled=false;}}}
    if(action==='task-detail')taskDetail(id);
    if(action==='upload')uploadModal(id);
    if(action==='request-fix')modal('Повторні правки',`<form id="fix-request-form" data-id="${id}"><input type="hidden" name="take_id" value="${b.dataset.take||''}">${field('Що виправити', '<textarea name="note" maxlength="2000"></textarea>')}<p>Створиться окреме завдання FIX, FIX2… Попередні записи збережуться.</p>${formEnd('Надіслати актору')}</form>`);
    if(['working','approved','revision'].includes(action))await changeStatus(id,action);
    if(action==='setup')setupModal();
    if(action==='deadline'){const t=state.tasks.find(t=>t.id===id);modal('Змінити дедлайн',`<form id="deadline-form" data-id="${id}">${field('Новий дедлайн',`<input type="datetime-local" name="deadline" value="${dateInput(t.deadline,userZone(state,t.assignee))}" data-zone="${userZone(state,t.assignee)}" required>`)}${formEnd()}`);}
    if(action==='episode-progress')showEpisodeProgress(id,Number(b.dataset.episode));
    if(action==='episode-tasks'){modal(`Серія ${b.dataset.episode}`,taskTable(visibleTasks().filter(t=>t.project_id===selectedProject&&t.episode===Number(b.dataset.episode))));}
    if(action==='zip')archivePicker(id,Number(b.dataset.episode));
    if(action==='inbox')inbox();
    if(action==='demo-take'&&demo){const t=state.tasks.find(t=>t.id===id);const next=structuredClone(state),nt=next.tasks.find(t=>t.id===id),tid=newID();next.takes.unshift({id:tid,task_id:id,version:Math.max(0,...next.takes.filter(v=>v.task_id===id).map(v=>v.version))+1,filename:'Demo_'+t.character+'.flac',bytes:1048576,created_at:new Date().toISOString(),demo:true,metadata:{sampleRate:48000,bits:24,channels:1}});if(['recording','correction'].includes(nt.stage)&&nt.status!=='approved')nt.status='review';act(next,{type:'uploaded',task_id:id,take_id:tid},next.users.find(u=>u.id===state.user.id));state=next;await finishTaskAction();notify('Демонстрація: здавання імітовано, у Telegram нічого не надіслано.');}
    if(action==='edit-user')editUser(id);
    if(action==='edit-project')editProject(id);
    if(action==='members')membersModal(id);
    if(action==='new-episode')episodeModal(id);
    if(action==='cast')castModal(id);
    
    
    if(action==='production-start'){await workflow({type:'start',task_id:id});await finishTaskAction();}
    if(action==='production-complete'){const t=state.tasks.find(x=>x.id===id);if(t.stage==='mixing'){await workflow({type:'complete',task_id:id});await finishTaskAction();notify('Зведення завершено');}else completeModal(id);}
    if(action==='edit-task')editTask(id);
    if(action==='rule')ruleModal();
    if(action==='access-approve'||action==='access-reject'){const u=user(id);if(action==='access-reject'&&!confirm('Відхилити заявку '+u.name+'?'))return;await workflow({type:'user',user_id:id,data:{roles:roles(u),access:action==='access-approve'?'active':'blocked'}});renderMain();notify(action==='access-approve'?'Доступ надано':'Заявку відхилено');}
    if(action==='credit-edit')creditModal(id);
    if(action==='credit-delete'){if(!confirm('Видалити запис про озвучення персонажа?'))return;await workflow({type:'credit-delete',data:{id}});renderMain();}
    if(action==='quiet-hours')quietHoursModal();
    if(action==='quiet-add'){$('#quiet-ranges').insertAdjacentHTML('beforeend',quietRange());}
    if(action==='quiet-remove')b.closest('.quiet-range').remove();
    if(action==='read-notices'){await workflow({type:'read-notices'});updateNoticeBell();inbox();}
    if(action==='read-notice'){await workflow({type:'read-notice',data:{id}});updateNoticeBell();inbox();}
    if(action==='notifications'){
      if(demo){modal('Особисті нагадування','<div class="notice">Після підключення бота Telegram запропонує одноразово дозволити повідомлення. Нагадування приходитимуть особисто, без повідомлень у групу.</div><p class="subtitle">У деморежимі сповіщення не надсилаються.</p>');return;}
      if(state.user.notify){await api('/notifications',{method:'POST',data:{enabled:false}});await refresh();notify('Нагадування вимкнено');return;}
      const tg=window.Telegram?.WebApp;if(!tg?.initData){await api('/notifications',{method:'POST',data:{enabled:true}});await refresh();notify('Сповіщення увімкнено. Натисніть Start у приватному чаті бота, якщо ще не зробили цього.');return;}if(!tg?.requestWriteAccess)throw new Error('Оновіть Telegram, щоб дозволити сповіщення.');
      tg.requestWriteAccess(async granted=>{if(!granted)return notify('Дозвіл не надано');try{await api('/notifications',{method:'POST',data:{enabled:true}});await refresh();notify('Особисті нагадування увімкнено');}catch(e){notify(e.message);}});
    }
    if(action==='reset'){modal('Скинути демонстрацію?','<p class="subtitle">Створені у цьому браузері демопроєкти, завдання та локальні прив’язки буде видалено.</p><div class="form-actions"><button class="button" data-close>Скасувати</button><button class="button danger" data-action="confirm-reset">Скинути демодані</button></div>');}
    if(action==='confirm-reset'){state=seed();upgradeDemo(state);localFiles.forEach(f=>URL.revokeObjectURL(f.url));localFiles.clear();persist();closeSheet();render();notify('Демонстрацію відновлено');}
  }catch(e){showError(e);}
});
document.addEventListener('change',async e=>{
  if(e.target.name==='audio'&&e.target.type==='file'){const files=Array.from(e.target.files),box=$('#selected-audio');box.hidden=!files.length;box.innerHTML=files.map((f,i)=>`<p><strong>${escape(f.name)}</strong> · ${bytes(f.size)} <button type="button" class="button small" data-action="remove-selected" data-index="${i}">Прибрати</button></p>`).join('');}


  if(e.target.dataset.reviewUser){const tid=e.target.dataset.reviewTask,draft=reviewDrafts.get(tid)||{};draft[e.target.dataset.reviewUser]=e.target.value;reviewDrafts.set(tid,draft);}
  if(e.target.dataset.projectFileFilter){projectFileFilters[e.target.dataset.projectFileFilter]=e.target.value;renderMain();}
  if(e.target.id==='show-others'){showOthers=e.target.checked;renderMain();}
  if(e.target.id==='task-stage')updateTaskPeople();
  if(e.target.id==='materials-project'){materialsProject=e.target.value;renderMain();}
 if(e.target.id==='materials-person'){materialsPerson=e.target.value;renderMain();}
 if(e.target.id==='materials-sort'){materialsSort=e.target.value;renderMain();}
 if(e.target.id==='status-filter'){filter=e.target.value;rememberRoute();renderMain();}
  if(e.target.id==='demo-role'){if(transferPending()){e.target.value=state.user.id;return notify('Дочекайтеся завершення завантажень перед зміною деморолі.');}showOthers=false;state.user=user(e.target.value);persist();render();}
  if(e.target.dataset.roleUser){try{if(demo)user(e.target.dataset.roleUser).role=e.target.value;else await api('/users/'+e.target.dataset.roleUser+'/role',{method:'POST',data:{role:e.target.value}});await refresh();notify('Роль оновлено');}catch(err){notify(err.message);}}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;rememberRoute();renderMain();}});
document.addEventListener('submit',async e=>{
  const f=e.target;if(['guest-form','batch-form','notion-import-form'].includes(f.id)||!f.id.endsWith('-form'))return;e.preventDefault();const b=Object.fromEntries(new FormData(f));const button=f.querySelector('button[type=submit]');button.disabled=true;if($('#form-error'))$('#form-error').textContent='';
  try{
    if(await productionForm(f,b)){if(['progress-import-form','quiet-hours-form'].includes(f.id)){if(f.id==='quiet-hours-form')notify('Збережено');return;}if(!['episode-controls-form','progress-import-form'].includes(f.id))await finishTaskAction();notify('Збережено');return;}
    if(f.id==='project-form'){b.paid=Number(b.paid)===1?1:0;if(demo){assertProjectCode(state,b.code);const pid=newID();state.projects.push({...b,id:pid,thread_id:null,chat_id:null});await workflow({type:'project-plan',project_id:pid,data:{count:Number(b.episode_count)}});}else await api('/projects',{method:'POST',data:b});}
    if(f.id==='task-form'){b.episode=Number(b.episode);if(b.deadline)b.deadline=fromInput(b.deadline,f.querySelector('[name=deadline]').dataset.zone||userZone(state,b.assignee||state.user.id));await workflow({type:'task-create',data:b});}
    if(f.id==='binding-form'){const r=await parseBinding();if(r.needsThread)throw new Error('Потрібно визначити ID гілки перед збереженням.');if(demo)Object.assign(project(b.project_id),{chat_id:r.chatId,thread_id:r.threadId,link:r.url});else await api('/projects/'+b.project_id+'/binding',{method:'POST',data:b});}
    if(f.id==='deadline-form'){const deadline=fromInput(b.deadline,f.querySelector('[name=deadline]').dataset.zone||userZone(state,b.assignee||state.user.id));if(demo)state.tasks.find(t=>t.id===f.dataset.id).deadline=deadline;else await api('/tasks/'+f.dataset.id,{method:'PATCH',data:{deadline}});}
    if(f.id==='upload-form'){
      const files=Array.from(f.elements.audio.files),task=state.tasks.find(t=>t.id===f.dataset.id);if(!files.length)throw new Error('Оберіть файли.');if(b.replaces&&files.length!==1)throw new Error('Для заміни одного файла оберіть один новий файл.');
      for(const file of files)validateFile(task.stage,file);
      await enqueueFiles(task.id,files,b.replaces||'');activeTaskId=null;inTaskView=false;closeSheet();return;

    }
    await finishTaskAction();notify(f.id==='upload-form'?(demo?'Демо: файли здано, Telegram не підключено.':'Файли надіслано.'):'Збережено');
  }catch(e){showError(e);}finally{setUploadBusy(false);button.disabled=false;}
});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeSheet();});
$('#modal').addEventListener('close',()=>{activeTaskId=null;inTaskView=false;document.documentElement.classList.remove('sheet-open');if(uploadPreviewUrl){URL.revokeObjectURL(uploadPreviewUrl);uploadPreviewUrl=null;}syncBack();});
window.addEventListener('beforeunload',e=>{if(pendingUpload||transferPending()){e.preventDefault();e.returnValue='';}});
window.addEventListener('popstate',e=>{
  if(!state)return;
  const route=e.state?.route||decodeRoute(location.hash);
  if($('#modal').open)$('#modal').close();
  // Forward navigation to a closed sheet restores its page, never stale form contents.
  if(e.state?.sheet)history.replaceState({...e.state,sheet:false},'',encodeRoute(route));
  applyRoute(route);render();window.scrollTo({top:e.state?.scroll||0});
});


function upgradeDemo(s){
 normalizeState(s);if(s.workflowVersion>=2){seedRoleDemo(s);return;}
 const added=[['translator1','Олена',['translator','editor']],['editor1','Данило',['editor']],['casting1','Ірина',['casting','actor']],['reviewer1','Назар',['reviewer']]];
 added.forEach(([id,name,rs])=>{if(!s.users.some(u=>u.id===id))s.users.push({id,name,username:'',role:rs[0],roles:rs,access:'active',notify:0});});
 for(const p of s.projects)for(const u of s.users)for(const r of roles(u))if(r!=='admin'&&!s.memberships.some(m=>m.project_id===p.id&&m.user_id===u.id&&m.role===r))s.memberships.push({project_id:p.id,user_id:u.id,role:r});
 // One editor/translator for each demo project, so the handoff is easy to explore.
 s.memberships=s.memberships.filter(m=>!(m.role==='editor'&&m.user_id==='translator1'));
 const a=s.users.find(isAdmin);if(a)for(const p of s.projects){const n=Math.max(0,...s.tasks.filter(t=>t.project_id===p.id).map(t=>t.episode))+1;act(s,{type:'episode',project_id:p.id,data:{number:n}},a);}
 s.workflowVersion=2;seedRoleDemo(s);
}
let stateRevision=0;
async function workflow(action){
 stateRevision++;
 if(demo){const next=structuredClone(state);act(next,action,next.users.find(u=>u.id===state.user.id));state=next;state.user=state.users.find(u=>u.id===state.user.id);persist();}
 else{await api('/workflow',{method:'POST',data:action});const next=await api('/state');stateRevision++;state=next;}
}
function currentFile(id){let file=state.takes.find(v=>v.id===id);const seen=new Set();while(file&&!seen.has(file.id)){seen.add(file.id);const next=state.takes.find(v=>v.metadata?.replaces===file.id);if(!next)break;file=next;}return file;}
function scriptFiles(t){return (t.script_take_ids||[]).map(currentFile).filter(Boolean);}
function scriptSection(t){const files=scriptFiles(t);const links=(t.script_links||[]).map(x=>`<a class="button" href="${escape(x.url)}" target="_blank" rel="noopener">${icon('download')}Субтитри · ${escape(x.name)}</a>`).join('');return links+(files.length?'<h3>Ваші індивідуальні субтитри</h3>'+files.map(v=>`<div class="script-download"><span>${escape(v.filename)}</span><button class="button small" data-action="download-take" data-id="${v.id}">${icon('download')}Скачати субтитри</button></div>`).join(''):'');}
function productionTask(t){if(t?.material_kind){episodeMaterials(t.project_id,t.episode);return;}
 if(!t)return;if(t.status==='planned')return notify('Цей етап ще не запущено. Адмін керує ним у списку етапів серії.');activeTaskId=t.id;const owner=t.status!=='planned'&&(canAdmin()||t.assignee===state.user.id&&(t.stage==='other'||roles(state.user).includes(STAGE_ROLE[t.stage])));const p=project(t.project_id),review=t.stage==='review';
 modal(`${escape(p.title)}${t.project_id==='general'?'':' · Серія '+t.episode}`,`<span class="eyebrow">${STAGES[t.stage]}</span><h3>${escape(taskLabel(t))}</h3>${t.notion_snapshot_id?`<button class="button primary" data-action="notion-read" data-id="${t.notion_snapshot_id}" data-task="${t.id}">Переглянути правки</button>`:''}${materialButton(t.project_id,t.episode)}${scriptSection(t)}${legacyLinks(t)}<dl class="binding-data"><dt>Виконавець</dt><dd>${escape(user(t.assignee)?.name)}</dd><dt>Дедлайн</dt><dd>${t.deadline?zonedDate(t.deadline,userZone(state,t.assignee)):'Після запуску'}</dd><dt>Статус</dt><dd>${badge(t.status)}</dd></dl>${state.cast.filter(c=>c.project_id===t.project_id&&c.episode===t.episode&&c.user_id===t.assignee&&c.character===t.character&&c.script_url).map(c=>`<a class="button" href="${escape(c.script_url)}" target="_blank" rel="noopener">Відкрити субтитри</a>`).join('')}${t.note?`<div class="notice">${escape(t.note)}</div>`:''}${t.output_url&&t.stage!=='correction'?`<a class="button" href="${escape(t.output_url)}" target="_blank" rel="noopener">Відкрити результат</a>`:''}<div class="form-actions wrap">
 ${owner&&t.status==='todo'?`<button class="button" data-action="production-start" data-id="${t.id}">Взяти в роботу</button>`:''}
 ${owner&&!review&&t.stage!=='casting'?`<button class="button" data-action="upload" data-id="${t.id}">${['review','approved'].includes(t.status)?'Замінити файли чи додати':({translation:'Додати переклад',editing:'Додати редактуру',casting:'Додати субтитри',recording:'Здати запис',correction:'Здати правки',mixing:'Додати результат зведення',other:'Додати результат'})[t.stage]}</button>${t.status!=='approved'&&!['recording','correction','translation','editing'].includes(t.stage)?`<button class="button primary" data-action="production-complete" data-id="${t.id}">Завершити етап</button>`:''}`:''}
 
 ${owner&&t.stage==='casting'?`<button class="button" data-action="batch-subs" data-id="${t.id}">${t.status==='approved'?'Редагувати розподіл і файли':'Роздати пачку субтитрів'}</button>`:''}
 ${demo&&owner&&!review&&t.stage!=='casting'?`<button class="button" data-action="demo-take" data-id="${t.id}">Демо: імітувати здавання</button>`:''}
 ${canRequestFix()&&['recording','correction'].includes(t.stage)&&state.takes.some(v=>v.task_id===t.id&&!v.local)?`<button class="button" data-action="request-fix" data-id="${t.id}">Запросити правки</button>`:''}
 ${t.stage==='mixing'&&roles(state.user).some(r=>['engineer','admin'].includes(r))?`<button class="button" data-action="zip" data-id="${t.project_id}" data-episode="${t.episode}">ZIP: перші записи та фікси</button>`:''}
 ${canAdmin()?`<button class="button" data-action="admin-status" data-id="${t.id}">Змінити статус</button><button class="button danger" data-action="delete-task-confirm" data-id="${t.id}">Видалити завдання</button><button class="button" data-action="edit-task" data-id="${t.id}">Виконавець і дедлайн</button>`:''}</div>
 ${state.tasks.filter(x=>x.project_id===t.project_id&&x.episode===t.episode&&x.output_url&&x.id!==t.id&&x.stage!=='correction').map(x=>`<p><a href="${escape(x.output_url)}" target="_blank" rel="noopener">${STAGES[x.stage]}: результат ${escape(user(x.assignee)?.name)}</a></p>`).join('')}
 ${review?reviewBoard(t,owner):`${state.jobs.filter(j=>j.task_id===t.id&&j.status!=='done').map(j=>`<div class="notice">${escape(j.status)} ${escape(j.error||'')}</div>`).join('')}<h3>Файли завдання</h3>${fileList(state.takes.filter(v=>v.task_id===t.id))}`}`);
 inTaskView=true;
}
const notionDrafts=new Map();
let notionPreview=null;
const reviewStatus={unchecked:'Ще не перевірено',fix:'Є правки',clear:'Немає правок'};
function reviewBoard(t,owner){const rows=reviewActors(state,t),pending=rows.filter(r=>!r.notified),done=rows.filter(r=>r.notified),draft=reviewDrafts.get(t.id)||{};
 const card=(r,heard)=>`<article class="review-actor"><div class="split"><strong>${escape(user(r.user_id)?.name)}</strong>${heard&&owner?`<button class="button small" data-action="review-edit" data-id="${t.id}" data-user="${r.user_id}">Змінити</button>`:''}</div><ul>${r.files.map(f=>`<li>${escape(f.filename)}</li>`).join('')||r.tasks.map(legacyLinks).join('')||'<li>Записи ще не надійшли</li>'}</ul>${owner&&!heard?`<button class="button small" data-action="notion-import" data-id="${t.id}" data-user="${r.user_id}">${notionDrafts.has(t.id+':'+r.user_id)?'✓ Правки з Notion додано':'Імпортувати правки з Notion'}</button>`:''}${heard?`<span class="badge ${r.result.status==='clear'?'approved':'revision'}">${reviewStatus[r.result.status]}</span>`:`${r.result?'<p>Файли оновлено — перевірте знову.</p>':''}${owner?`<select aria-label="Статус перевірки ${escape(user(r.user_id)?.name)}" data-review-user="${r.user_id}" data-review-task="${t.id}" ${r.ready?'':'disabled'}>${Object.entries(reviewStatus).map(([v,l])=>`<option value="${v}" ${(draft[r.user_id]||'unchecked')===v?'selected':''}>${l}</option>`).join('')}</select>`:'<span>Ще не перевірено</span>'}`}</article>`;
 return `${owner?`<div class="form-actions wrap"><button class="button" data-action="review-downloads" data-id="${t.id}">Отримати записи акторів</button><button class="button primary" data-action="review-preview" data-id="${t.id}" ${pending.length?'':'disabled'}>Сповістити акторів</button></div>`:''}<p class="subtitle">Оберіть результат для кожного актора. Неперевірені залишаться тут. Перед надсиланням перевірте список файлів.</p><div class="review-columns"><section><h3>На вислуховування · ${pending.length}</h3>${pending.map(r=>card(r,false)).join('')||'<p>Усіх вислухано.</p>'}</section><section><h3>Вислухані · ${done.length}</h3>${done.map(r=>card(r,true)).join('')||'<p>Після сповіщення актори з’являться тут.</p>'}</section></div>`;
}
function previewReview(tid){const t=state.tasks.find(t=>t.id===tid),draft=reviewDrafts.get(tid)||{},rows=reviewActors(state,t).filter(r=>!r.notified&&r.ready&&['fix','clear'].includes(draft[r.user_id]));if(!rows.length)throw new Error('Оберіть «Є правки» або «Немає правок» хоча б для одного актора.');if(state.notion_enabled&&rows.some(r=>draft[r.user_id]==='fix'&&!notionDrafts.has(tid+':'+r.user_id)))throw new Error('Спочатку імпортуйте правки Notion для акторів зі статусом «Є правки».');reviewPreview={task_id:tid,entries:rows.map(r=>({user_id:r.user_id,status:draft[r.user_id],take_ids:r.take_ids,...(draft[r.user_id]==='fix'&&notionDrafts.has(tid+':'+r.user_id)?{notion_import:notionDrafts.get(tid+':'+r.user_id).id}: {})}))};modal('Перевірте перед сповіщенням',`<p>${escape(project(t.project_id).title)} · Серія ${t.episode}</p><div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Актор</th><th>Записи, що перевірені / файли для актора</th><th>Результат</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${escape(user(r.user_id)?.name)}</th><td><b>Перевірені записи</b><ul>${r.files.map(v=>`<li>${escape(v.filename)}</li>`).join('')}</ul>${draft[r.user_id]==='fix'?'<b>Субтитри у завданні на правки</b><ul>'+[...new Map(r.tasks.flatMap(scriptFiles).map(v=>[v.id,v])).values()].map(v=>`<li>${escape(v.filename)}</li>`).join('')+'</ul><small>Правки Notion: '+escape(notionDrafts.has(tid+':'+r.user_id)?notionDrafts.get(tid+':'+r.user_id).view.name+' · '+notionDrafts.get(tid+':'+r.user_id).alias+' · '+notionDrafts.get(tid+':'+r.user_id).pages.length+' карток':'не прикріплено')+'</small>':'Нові файли й завдання не надсилаються.'}</td><td>${reviewStatus[draft[r.user_id]]}</td></tr>`).join('')}</tbody></table></div><p>Неперевірені актори залишаться на вислуховування.</p><div class="form-actions"><button class="button" data-action="review-back" data-id="${tid}">Назад до перевірки</button><button class="button primary" data-action="review-send" data-id="${tid}">Підтвердити й сповістити</button></div>`);}
async function downloadBlob(route,name){
 if(window.Telegram?.WebApp?.initData){const data=await api('/download-link',{method:'POST',data:{route}}),tg=window.Telegram.WebApp;
   modal('Завантажити файл',`<p>${escape(name)}</p><p>Посилання діє 10 хвилин. Завантаження відкриється у браузері.</p><button class="button primary" data-action="open-download" data-url="${escape(data.url)}">Завантажити у браузері</button>`);return;
 }
 const response=await api(route,{raw:true}),blob=await response.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),60000);
}

