const onboardingSteps=[['Ласкаво просимо до Fomalhaut Studio','Тут команда веде серії від перекладу до зведення. На головній — активні завдання, а внизу — навігація.'],['Проєкти та команда','Відкрийте проєкт, щоб побачити серії, відповідальних і файли. Одна людина може мати кілька ролей. Усі учасники бачать усі файли.'],['Завдання й дедлайни','Відкрийте своє завдання, додайте результат і завершіть етап. Наступний виконавець отримає сповіщення. Таблиця дедлайнів доступна зі сторінки завдань.'],['Записи та правки','Правкер позначає, кому потрібні правки, і сповіщає акторів. Правки здаються окремим завданням.'],['Сповіщення й акаунт','Дзвіночок відкриває журнал повідомлень. У меню акаунта можна дозволити особисті повідомлення Telegram і повторити це знайомство.'],['Адміністраторам','У Команді керуйте доступом і створюйте гостей без входу. Додайте гостя до проєкту, призначте йому завдання та відкрийте його завдання для здавання. Так само можна здати файл за учасника. Інші адміни отримують сповіщення про ваші зміни.']];
function showOnboarding(step){const steps=canAdmin()?onboardingSteps:onboardingSteps.slice(0,5);step=Math.min(step,steps.length-1);modal(steps[step][0],`<p class="subtitle">Крок ${step+1} із ${steps.length}</p><p style="line-height:1.7;margin:24px 0">${steps[step][1]}</p><div class="form-actions">${step?`<button class="button" data-action="onboarding" data-step="${step-1}">Назад</button>`:''}${step<steps.length-1?`<button class="button primary" data-action="onboarding" data-step="${step+1}">Далі</button>`:'<button class="button primary" data-action="onboarding-done">Почати роботу</button>'}<button class="button" data-action="onboarding-done">Пропустити</button></div>`);}
document.addEventListener('submit',async e=>{if(e.target.id!=='guest-form')return;e.preventDefault();try{await workflow({type:'guest',data:{name:new FormData(e.target).get('name')}});closeSheet();await refresh();notify('Гостя створено. Додайте його до команди проєкту.');}catch(error){showError(error);}});



let subtitleBatch=null;
function validateFile(stage,file){if(!file||!file.size||file.size>MAX_UPLOAD_BYTES)throw new Error('Потрібен непорожній файл до 2000 МБ.');if(!allowedUpload(stage,file.name))throw new Error('Для цього етапу дозволено лише відповідні формати файлів: субтитри та ZIP для перекладу, редактури й ролей; WAV/FLAC для записів.');}
async function submitFile(taskId,file,replaces='',stageCasting=false,unsplit=false,transfer=null){
 const task=state.tasks.find(t=>t.id===taskId);validateFile(task.stage,file);
 if(demo){const digest=await fileDigest(file);const duplicate=state.takes.find(v=>v.task_id===taskId&&v.metadata?.client_digest===digest);if(duplicate)throw new Error('Цей файл уже додано. Вміст збігається з '+duplicate.filename);const id=newID(),next=structuredClone(state),nt=next.tasks.find(t=>t.id===taskId);next.takes.push({id,task_id:taskId,actor_id:task.assignee,version:Math.max(0,...next.takes.filter(t=>t.task_id===taskId).map(t=>t.version))+1,filename:file.name,bytes:file.size,metadata:{client_digest:digest,kind:['recording','correction'].includes(task.stage)?'audio':'document',original_name:file.name,replaces:replaces||null},created_at:new Date().toISOString(),demo:true});localFiles.set(id,{file,url:URL.createObjectURL(file)});if(['recording','correction'].includes(nt.stage)&&nt.status!=='approved')nt.status='review';act(next,{type:'uploaded',task_id:taskId,take_id:id},next.users.find(u=>u.id===state.user.id));state=next;persist();return id;}
 const result=await uploadRequest(taskId,file,{Authorization:`Bearer ${token}`,'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name),...(stageCasting?{'X-Stage-Casting':'1'}:{}),...(unsplit?{'X-Unsplit':'1'}:{}),...(replaces?{'X-Replaces-Take':replaces}:{})},percent=>{if(transfer){transfer.percent=percent;updateTransfers();}});
 if(transfer){transfer.status='processing';transfer.jobId=result.id;transfer.percent=100;updateTransfers();}

 for(let attempt=0;attempt<7200;attempt++){const revision=stateRevision,nextState=await api('/state');if(revision===stateRevision){stateRevision++;state=nextState;}const job=nextState.jobs.find(j=>j.id===result.id);if(['failed','uncertain'].includes(job?.status))throw new Error(job.error||'Перевірте стан файла');const take=nextState.takes.find(v=>v.metadata?.upload_job_id===result.id);if(take)return take.id;await new Promise(r=>setTimeout(r,1000));}throw new Error('Обробка ще триває. Не надсилайте повторно: перевірте чергу в завданні.');
}
function batchModal(taskId){const ts=state.tasks.filter(t=>t.source_cast_task_id===taskId||t.stage==='recording'&&t.script_take_ids?.some(id=>state.takes.some(v=>v.id===id&&v.task_id===taskId)));const files=state.takes.filter(v=>v.task_id===taskId&&!v.metadata?.unsplit&&(v.metadata?.staged_path||!v.metadata?.distributed_users&&!ts.length||ts.some(t=>t.script_take_ids?.includes(v.id))));subtitleBatch={taskId,id:newID(),files:files.map(v=>({take_id:v.id,name:v.metadata?.original_name||v.filename})),unsplit:null,rows:files.map(v=>({users:ts.some(t=>t.script_take_ids?.includes(v.id))?ts.filter(t=>t.script_take_ids?.includes(v.id)).map(t=>t.assignee):matchSubtitle(state,v.metadata?.original_name||v.filename,state.tasks.find(t=>t.id===taskId).project_id),alias:''}))};modal('Роздати пачку субтитрів',`<label class="dropzone">Індивідуальні субтитри або ZIP<input id="batch-files" type="file" multiple accept="${SUBTITLE_EXTENSIONS.join(',')}"></label><label class="field">Нерозділений файл ролей (ASS, необов’язково)<input id="unsplit-file" type="file" accept=".ass"></label><p>НікАктора_Проєкт_Серія. Після вибору файлів перевірте одержувачів, далі — таблицю підтвердження.</p><div id="batch-rows">${batchRows()}</div><div class="form-actions"><button class="button primary" data-action="batch-preview">Перевірити розподіл</button></div>`);}
function batchRows(){const t=state.tasks.find(t=>t.id===subtitleBatch.taskId),people=state.users.filter(u=>u.access==='active'&&roles(u).includes('actor')&&state.memberships.some(m=>m.project_id===t.project_id&&m.user_id===u.id&&m.role==='actor'));return subtitleBatch.files.map((item,i)=>{const matches=matchSubtitle(state,item.name,t.project_id),row=subtitleBatch.rows[i],chosen=row?.users|| (matches.length===1?matches:[]);return `<fieldset data-batch-row="${i}"><legend>${escape(item.name)}</legend><button type="button" class="button small" data-action="batch-remove" data-index="${i}">Прибрати файл</button><p>${matches.length===1?'Розпізнано — перевірте одержувача':'Потрібне ручне призначення'}</p><button type="button" class="button small" data-action="batch-all">Усім акторам проєкту</button><button type="button" class="button small" data-action="batch-none">Очистити вибір</button>${people.map(u=>`<label class="batch-person"><input type="checkbox" name="recipient" value="${u.id}" ${chosen.includes(u.id)?'checked':''}>${escape(u.name)}</label>`).join('')}<label>Аліас на майбутнє (для одного актора)<input data-alias maxlength="80" value="${escape(row?.alias||'')}" placeholder="${escape(item.name.split('_')[0])}"></label></fieldset>`;}).join('');}
function renderBatchMapping(){modal('Призначення файлів',`<div id="batch-rows">${batchRows()}</div><div class="form-actions"><button class="button primary" data-action="batch-preview">Перевірити розподіл</button></div>`);}
function previewBatch(){const b=subtitleBatch;if(!b?.files.length)throw new Error('Оберіть файли для акторів.');b.rows=Array.from(document.querySelectorAll('[data-batch-row]')).map(row=>({users:Array.from(row.querySelectorAll('[name=recipient]:checked')).map(x=>x.value),alias:row.querySelector('[data-alias]').value.trim()}));if(b.rows.some(r=>!r.users.length))throw new Error('Кожен файл потрібно призначити хоча б одному актору.');if(b.rows.some(r=>r.alias&&r.users.length!==1))throw new Error('Аліас можна зберегти для одного актора.');for(const f of b.files)if(f.file)validateFile('casting',f.file);if(b.unsplit){validateFile('casting',b.unsplit);if(!/\.ass$/i.test(b.unsplit.name))throw new Error('Нерозділений файл має бути ASS.');}
 const ids=[...new Set(b.rows.flatMap(r=>r.users))];modal('Перевірте, кому підуть файли',`<div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Нік актора</th><th>Файли для актора</th></tr></thead><tbody>${ids.map(uid=>`<tr><th>${escape(user(uid)?.name)}</th><td><ul>${b.files.filter((f,i)=>b.rows[i].users.includes(uid)).map(f=>`<li>${escape(f.name)}</li>`).join('')}</ul></td></tr>`).join('')}</tbody></table></div>${b.unsplit?`<p>Спільний нерозділений файл: ${escape(b.unsplit.name)}. Зберігається у матеріалах рольовика.</p>`:''}<p>Після підтвердження актори отримають завдання та прикріплені файли.</p><p id="batch-status" role="status"></p><div class="form-actions"><button class="button" data-action="batch-back">Назад до призначення</button><button class="button primary" data-action="batch-send">Підтвердити й надіслати</button></div>`);}
async function sendBatch(button){
 if(pendingUpload||transferPending())return notify('Зачекайте завершення черги завантажень.');const b=subtitleBatch;if(!b?.rows.length)throw new Error('Спочатку перевірте розподіл.');
 const revision=modalRevision,item={id:newID(),taskId:b.taskId,file:{name:'Пачка субтитрів',size:0},batch:true,startedAt:new Date().toISOString(),status:'checking',percent:0,message:'Перевірка файлів'};button.disabled=true;setUploadBusy(true);transferQueue.push(item);updateTransfers();
 try{
 await assertDistinctFiles([...b.files.filter(f=>f.file).map(f=>f.file),...(b.unsplit?[b.unsplit]:[])]);
 if(b.unsplit&&!b.unsplit_id){item.status='uploading';item.message='Нерозділений файл ролей';b.unsplit_id=await submitFile(b.taskId,b.unsplit,'',false,true,item);}
 for(let i=0;i<b.files.length;i++){const f=b.files[i];item.status='uploading';item.message=`Субтитри ${i+1} / ${b.files.length}: ${f.name}`;updateTransfers();if(f.file&&!f.take_id)f.take_id=await submitFile(b.taskId,f.file,'',true,false,item);}
 await workflow({type:'cast-batch',task_id:b.taskId,data:{batch_id:b.id,files:b.files.map((f,i)=>({...b.rows[i],...(f.link?{link:f.link,filename:f.name}:{take_id:f.take_id})}))}});
 item.status='processing';item.message='Публікація розподілу в Telegram';updateTransfers();
 if(!demo){for(let i=0;i<7200;i++){const rev=stateRevision,next=await api('/state');if(rev===stateRevision){stateRevision++;state=next;}const jobs=next.jobs.filter(j=>j.task_id===b.taskId);const failed=jobs.find(j=>['failed','uncertain'].includes(j.status)&&j.created_at>=item.startedAt);if(failed)throw new Error(failed.error||'Перевірте гілку й завдання рольовика.');if(!jobs.some(j=>['uploading','queued','processing','publishing'].includes(j.status)))break;if(i===7199)throw new Error('Обробка ще триває. Перевірте чергу сервера.');await new Promise(r=>setTimeout(r,1000));}}
 item.status='done';item.percent=100;item.message='Субтитри розподілено';updateNoticeBell();notify(demo?'Демо: субтитри розподілено.':'Субтитри розподілено й надіслано.');
 if(modalRevision===revision){const assigned=state.tasks.filter(t=>t.source_cast_task_id===b.taskId);modal('Результат розподілу',`<table class="deadline-table"><thead><tr><th>Актор</th><th>Завдання</th></tr></thead><tbody>${assigned.map(t=>`<tr><td>${escape(user(t.assignee)?.name)}</td><td>${t.status==='planned'?'Очікує ручного запуску':statusNames[t.status]}</td></tr>`).join('')}</tbody></table>`);}
 }catch(e){item.status='failed';item.message=e.message+' Відкрийте завдання рольовика для перевірки й продовження.';notify(item.message);if(modalRevision===revision)showError(e);}finally{setUploadBusy(false);updateTransfers();button.disabled=false;}
}

function attachModal(taskId){subtitleBatch={taskId,id:newID(),files:[],rows:[]};modal('Прикріпити надіслані файли',`<label class="field">Посилання на файли Telegram (по одному в рядку)<textarea id="telegram-file-links" rows="6" placeholder="https://t.me/c/…"></textarea></label><p>Бот отримає назви доступних йому файлів і розпізнає акторів за ніками та аліасами.</p><div class="form-actions"><button class="button primary" data-action="resolve-files" data-id="${taskId}">Отримати назви файлів</button></div>`);}
async function resolveAttached(taskId){const links=$('#telegram-file-links').value.split(/\s+/).filter(Boolean);if(!links.length)throw new Error('Вставте посилання на файли.');let files;if(demo){files=links.map(link=>{const parsed=parseTelegramLink(link),take=state.takes.find(v=>String(v.chat_id)===parsed.chatId&&v.message_id===parsed.messageId);if(!take)throw new Error('Демо не підключено до Telegram. Скористайтеся кнопкою «Роздати пачку субтитрів».');return {take_id:take.id,name:take.metadata?.original_name||take.filename};});}else{files=(await api('/tasks/'+taskId+'/telegram-files',{method:'POST',data:{links}})).files;state=await api('/state');}subtitleBatch.files=files;renderBatchMapping();}
function manualAttach(taskId){modal('Ручне прикріплення',`<label class="field">Назва файла<input id="manual-file-name" placeholder="Нік_Проєкт_Серія.ass"></label><label class="field">Посилання на файл Telegram<input id="manual-file-link" type="text" placeholder="https://t.me/c/…"></label><p>Назва й посилання вводяться вручну. Застосунок не підтверджує вміст такого файла.</p><button class="button primary" data-action="manual-preview" data-id="${taskId}">Призначити одержувачів</button>`);}
function manualAttachPreview(taskId){const name=$('#manual-file-name').value.trim(),link=$('#manual-file-link').value.trim();parseTelegramLink(link);if(!subtitleFile(name))throw new Error('Вкажіть назву файла субтитрів або ZIP із розширенням.');subtitleBatch={taskId,id:newID(),files:[{name,link}],rows:[]};renderBatchMapping();}
function reviewDownloads(taskId){const t=state.tasks.find(t=>t.id===taskId),rows=reviewActors(state,t);modal('Отримати записи акторів',`<div class="form-actions"><button class="button" data-action="review-select-all">Обрати всіх</button><button class="button" data-action="review-select-none">Зняти вибір</button></div>${rows.map(r=>`<label class="batch-person"><input type="checkbox" data-review-download value="${r.user_id}" ${r.files.length?'checked':'disabled'}>${escape(user(r.user_id)?.name)} · ${r.files.length} файлів</label>`).join('')}<div class="form-actions"><button class="button" data-close>Назад</button><button class="button primary" data-action="review-zip" data-id="${taskId}">Завантажити ZIP</button></div>`);}
const projectFileFilters={episode:'all',person:'all',stage:'all'};
function projectFiles(pid){const ts=state.tasks.filter(t=>t.project_id===pid),selected=ts.filter(t=>(projectFileFilters.episode==='all'||t.episode===Number(projectFileFilters.episode))&&(projectFileFilters.stage==='all'||t.stage===projectFileFilters.stage));const files=state.takes.filter(v=>selected.some(t=>t.id===v.task_id)&&(projectFileFilters.person==='all'||(v.actor_id||state.tasks.find(t=>t.id===v.task_id)?.assignee)===projectFileFilters.person));const select=(key,label,entries)=>`<label class="field">${label}<select data-project-file-filter="${key}"><option value="all">Усі</option>${entries.map(([v,l])=>`<option value="${v}" ${projectFileFilters[key]===String(v)?'selected':''}>${escape(l)}</option>`).join('')}</select></label>`;return selected.map(legacyLinks).join('')+`<div class="filters">${select('episode','Серія',[...new Set(ts.map(t=>t.episode))].sort((a,b)=>a-b).map(n=>[n,n]))}${select('person','Виконавець',state.users.map(u=>[u.id,u.name]))}${select('stage','Тип файла',Object.entries({...STAGES,casting:'Ролі',recording:'Перші записи',correction:'Фікси'}))}</div><p>${files.length} файлів</p>`+fileList(files);}
document.addEventListener('change',e=>{if(e.target.id==='unsplit-file')subtitleBatch.unsplit=e.target.files[0]||null;if(e.target.id==='batch-files'){captureBatchRows();subtitleBatch.files.push(...Array.from(e.target.files).map(file=>({file,name:file.name,take_id:null})));e.target.value='';$('#batch-rows').innerHTML=batchRows();}});

let deadlineView='table',deadlineMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
function calendarTable(ts){const start=new Date(deadlineMonth),offset=(start.getDay()+6)%7;start.setDate(1-offset);const key=d=>`${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;return `<div class="calendar-toolbar"><button class="button" data-action="calendar-prev">←</button><b>${deadlineMonth.toLocaleDateString('uk-UA',{month:'long',year:'numeric'})}</b><button class="button" data-action="calendar-next">→</button></div><div class="deadline-scroll"><table class="calendar-table"><thead><tr>${['Пн','Вт','Ср','Чт','Пт','Сб','Нд'].map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,week)=>`<tr>${Array.from({length:7},(_,day)=>{const date=new Date(start);date.setDate(start.getDate()+week*7+day);return `<td class="${date.getMonth()!==deadlineMonth.getMonth()?'outside':''}"><b>${date.getDate()}</b>${ts.filter(t=>t.deadline&&dateInput(t.deadline,userZone(state,t.assignee)).slice(0,10)===`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`).map(t=>`<button data-action="edit-task" data-id="${t.id}">${escape(project(t.project_id)?.title)} · ${t.episode}<br>${STAGES[t.stage]} · ${escape(user(t.assignee)?.name)}<br>${escape(taskLabel(t))} · ${statusNames[t.status]}<br>${t.deadline?zonedDate(t.deadline,userZone(state,t.assignee)):''}</button>`).join('')}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function seedRoleDemo(s){if(s.roleDemoVersion===1){seedReviewDemo(s);return;}const a=s.users.find(isAdmin),pid=s.projects[0]?.id;if(!a||!pid)return;
 for(const [stage,role] of Object.entries(STAGE_ROLE)){const u=s.users.find(u=>roles(u).includes(role));if(!u)continue;act(s,{type:'task-create',data:{project_id:pid,episode:20,stage,assignee:u.id,character:'Демо · '+STAGES[stage],note:'Спробуйте роботу цього напрямку. Це незалежне демонстраційне завдання.'}},a);}
 act(s,{type:'task-create',data:{project_id:pid,episode:20,stage:'other',assignee:a.id,character:'Демо · підготувати реліз'}},a);
 s.roleDemoVersion=1;seedReviewDemo(s);
}
function seedReviewDemo(s){if(s.reviewDemoVersion)return;const a=s.users.find(isAdmin),pid=s.projects[0]?.id,checker=s.users.find(u=>roles(u).includes('reviewer')),caster=s.users.find(u=>roles(u).includes('casting'));if(!a||!checker||!caster)return;
 const make=(stage,assignee,character)=>{act(s,{type:'task-create',data:{project_id:pid,episode:21,stage,assignee,character}},a);return s.tasks.at(-1);};
 make('review',checker.id,'Демо · вислуховування трьох акторів');const subs=make('casting',caster.id,'Демо · індивідуальні субтитри');subs.status='approved';
 for(const u of s.users.filter(u=>roles(u).includes('actor')).slice(0,3)){
  const t=make('recording',u.id,'Демо · репліки '+u.name);t.status='review';const scriptId=newID();t.script_take_ids=[scriptId];
  s.takes.push({id:scriptId,task_id:subs.id,version:s.takes.filter(v=>v.task_id===subs.id).length+1,filename:u.name+'_Demo_21.srt',bytes:120,created_at:new Date().toISOString(),demo:true,demo_content:'1\n00:00:01,000 --> 00:00:03,000\nЦе демонстраційна репліка для перевірки застосунку.\n',metadata:{kind:'document'}});
  s.takes.push({id:newID(),task_id:t.id,actor_id:u.id,version:1,filename:u.name+'_Demo_E21.flac',bytes:1048576,created_at:new Date().toISOString(),demo:true,metadata:{sampleRate:48000,bits:24,channels:1}});
 }
 s.reviewDemoVersion=1;
}
void init();

function reminderForm(){const p=state.profiles.find(p=>p.user_id===state.user.id)||{};return `<form id="reminders-form">${field('Повторення після дедлайну',`<select name="interval">${[[0,'Не нагадувати'],[6,'Кожні 6 годин'],[12,'Кожні 12 годин'],[24,'Щодня'],[48,'Раз на 2 дні'],[72,'Раз на 3 дні'],[168,'Щотижня']].map(([v,l])=>`<option value="${v}" ${(p.reminder_hours??24)===v?'selected':''}>${l}</option>`).join('')}</select>`)}${field('Нагадати про найближчий дедлайн за днів (0 — вимкнено)',`<input name="ahead" type="number" min="0" max="30" value="${p.reminder_days||0}" required>`)}${formEnd('Зберегти нагадування')}`;}
function archivePicker(pid,episode){const superseded=new Set(state.takes.map(v=>v.metadata?.replaces).filter(Boolean));const files=state.takes.filter(v=>!superseded.has(v.id)&&state.tasks.some(t=>t.id===v.task_id&&t.project_id===pid&&t.episode===episode&&['recording','correction'].includes(t.stage)));modal('Перші записи та фікси',`<p>Оберіть потрібні файли. За замовчуванням обрано всі актуальні версії.</p><button class="button" data-action="select-archive" data-value="all">Обрати всі</button><button class="button" data-action="select-archive" data-value="none">Зняти вибір</button>${files.map(v=>`<label class="field"><span><input type="checkbox" data-archive-file value="${v.id}" checked> ${escape(v.filename)} · ${bytes(v.bytes)}</span></label>`).join('')||empty('Записів ще немає.')}<button class="button primary" data-action="download-archive" data-id="${pid}" data-episode="${episode}">Завантажити ZIP</button>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;try{
 if(action==='launch-episode')episodeControls(id);
 if(action==='admin-status'){const t=state.tasks.find(t=>t.id===id);modal('Статус завдання',`<form id="status-form" data-id="${id}">${field('Новий статус',`<select name="status">${['todo','working','review','approved'].map(k=>`<option value="${k}" ${t.status===k?'selected':''}>${k==='approved'?'Закрити без виконання':statusNames[k]}</option>`).join('')}</select>`)}<p>Історія файлів зберігається. Виконавець отримає сповіщення.</p>${formEnd()}</form>`);}
 if(action==='delete-task-confirm')modal('Видалити завдання?',`<p>Завдання зникне зі списків. Файли в Telegram залишаться, запис в історії сервера збережеться.</p><button class="button danger" data-action="delete-task" data-id="${id}">Видалити завдання зі списків</button>`);
 if(action==='delete-task'){await workflow({type:'task-delete',task_id:id});activeTaskId=null;closeSheet();await refresh();}
 if(action==='select-archive')document.querySelectorAll('[data-archive-file]').forEach(x=>x.checked=b.dataset.value==='all');
 if(action==='materials-zip'||action==='download-archive'){const ids=[...document.querySelectorAll(action==='materials-zip'?'[data-material-file]:checked':'[data-archive-file]:checked')].map(x=>x.value);if(!ids.length)throw new Error('Оберіть хоча б один файл.');if(demo)return notify('Архів із Telegram доступний на підключеному сервері.');b.disabled=true;try{const route=action==='materials-zip'?'/materials/archive':`/projects/${id}/episodes/${b.dataset.episode}/archive`;await downloadBlob(route+'?'+ids.map(x=>'file='+encodeURIComponent(x)).join('&'),'Матеріали.zip');}finally{b.disabled=false;}}
 }catch(err){showError(err);}});

function episodeControls(id){const e=state.episodes.find(e=>e.id===id);if(!e)return;const ts=state.tasks.filter(t=>t.project_id===e.project_id&&t.episode===e.number&&!t.independent);modal(`${escape(project(e.project_id).title)} · Серія ${e.number}`,`<form id="episode-controls-form" data-id="${e.id}" data-project="${e.project_id}" data-number="${e.number}"><div class="form-actions"><button type="button" class="button" data-action="all-modes" data-value="manual">Зробити все ручним</button><button type="button" class="button" data-action="all-modes" data-value="auto">Зробити все автоматичним</button></div><p>Автоматичний етап почнеться, коли готовий попередній результат. Ручний чекатиме вашого дозволу; після нього процес продовжиться до наступної зупинки.</p><div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Етап</th><th>Режим запуску</th><th>Стан / дія</th></tr></thead><tbody>${PIPELINE.map(k=>{const tasks=ts.filter(t=>t.stage===k),waiting=e.pendingStages?.includes(k),running=tasks.some(t=>!['planned','approved'].includes(t.status)),done=tasks.length&&tasks.every(t=>t.status==='approved'),canStart=waiting||k==='translation'&&!e.started;return `<tr><th>${STAGES[k]}</th><td><select name="mode_${k}" aria-label="Режим: ${STAGES[k]}"><option value="auto" ${e.stageModes?.[k]!=='manual'?'selected':''}>Автоматично</option><option value="manual" ${e.stageModes?.[k]==='manual'?'selected':''}>Ручний</option></select></td><td>${done?'Завершено':running?'У процесі':waiting?'Очікує дозволу':'Ще не запущено'}${canStart?`<button type="submit" class="button small" data-launch-stage="${k}">${k==='translation'&&!e.started?'Почати серію зараз':'Дозволити запуск'}</button>`:''}</td></tr>`;}).join('')}</tbody></table></div>${field('Після зведення цієї серії почати наступну',`<select name="nextMode"><option value="manual" ${e.nextMode!=='auto'?'selected':''}>Ручний запуск адміном</option><option value="auto" ${e.nextMode==='auto'?'selected':''}>Автоматично</option></select>`)}<p>Можна відкрити наступну серію й натиснути «Почати серію зараз», не чекаючи завершення цієї.</p>${formEnd('Зберегти режими')}<button class="button danger" data-action="delete-episode-preview" data-id="${e.id}">Видалити серію</button>`);}
document.addEventListener('submit',e=>{if(e.target.id==='episode-controls-form')e.target.dataset.start=e.submitter?.dataset.launchStage||'';},true);

const birthdayMonths=['Січень','Лютий','Березень','Квітень','Травень','Червень','Липень','Серпень','Вересень','Жовтень','Листопад','Грудень'];
function birthdayForm(){const p=state.profiles.find(p=>p.user_id===state.user.id)||{};return `<section class="aside-card"><h2>День народження</h2><p>Лише день і місяць. Дата відображатиметься в календарі команди.</p><div class="form-actions"><button class="button" data-action="birthdays-list">Список днів народження</button><button class="button" data-action="birthdays-calendar">Календар</button></div><form id="birthday-form">${field('День',`<input name="day" type="number" min="1" max="31" value="${p.birthday?.day||''}" placeholder="День">`)}${field('Місяць',`<select name="month"><option value="">Не вказано</option>${birthdayMonths.map((m,i)=>`<option value="${i+1}" ${p.birthday?.month===i+1?'selected':''}>${m}</option>`).join('')}</select>`)}${field('Нагадування про дні народження команди',`<select name="enabled"><option value="0">Вимкнено</option><option value="1" ${p.birthday_enabled?'selected':''}>Увімкнено</option></select>`)}${field('За скільки днів (0 — у день народження)',`<input name="ahead" type="number" min="0" max="30" value="${p.birthday_ahead??1}" required>`)}<small>Щоб прибрати дату, очистіть день і виберіть «Не вказано». Для Telegram потрібен дозвіл на повідомлення від бота. 29 лютого в невисокосний рік — нагадування 28 лютого.</small>${formEnd('Зберегти')}</section>`;}
function birthdays(calendar){const entries=state.users.filter(u=>u.access==='active').map(u=>({u,b:state.profiles.find(p=>p.user_id===u.id)?.birthday})).filter(x=>x.b).sort((a,b)=>a.b.month-b.b.month||a.b.day-b.b.day);const rows=entries.map(x=>`<tr><td>${x.b.day} ${birthdayMonths[x.b.month-1]}</td><td>${escape(x.u.name)}</td></tr>`).join('');modal(calendar?'Календар днів народження':'Дні народження команди',`<div class="form-actions"><button class="button" data-action="birthdays-list">Список</button><button class="button" data-action="birthdays-calendar">Календар</button></div>${calendar?`<div class="birthday-grid">${birthdayMonths.map((m,i)=>`<section><h3>${m}</h3>${entries.filter(x=>x.b.month===i+1).map(x=>`<p><b>${x.b.day}</b> · ${escape(x.u.name)}</p>`).join('')||'<p>Немає вказаних дат</p>'}</section>`).join('')}</div>`:rows?`<table class="deadline-table"><thead><tr><th>Дата</th><th>Учасник</th></tr></thead><tbody>${rows}</tbody></table>`:empty('Учасники ще не вказали дні народження.')}`);}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='birthdays-list'||a==='birthdays-calendar')birthdays(a==='birthdays-calendar');});

document.addEventListener('click',async e=>{if(e.target.closest('#session-logout')){if(transferPending())return notify('Дочекайтеся завершення завантажень перед виходом.');try{await api('/logout',{method:'POST'});}finally{sessionStorage.removeItem('fs-token');location.reload();}}});

function legacyLinks(t){return (t.legacy_links||[]).length?`<section class="notice"><b>${escape(STAGES[t.stage])} · ${escape(user(t.assignee)?.name)} · попередні матеріали</b>${t.legacy_links.map((url,i)=>`<p><a href="${escape(url)}" target="_blank" rel="noopener">Відкрити файл ${i+1} у Telegram</a></p>`).join('')}</section>`:'';}
function captureBatchRows(){if(!subtitleBatch)return;for(const row of document.querySelectorAll('[data-batch-row]'))subtitleBatch.rows[Number(row.dataset.batchRow)]={users:[...row.querySelectorAll('[name=recipient]:checked')].map(x=>x.value),alias:row.querySelector('[data-alias]').value.trim()};}
let progressImport=null;
function importRow(stage){return `<fieldset data-import-row><legend>${STAGES[stage]}</legend><input type="hidden" name="stage" value="${stage}"><label class="field">Виконавець<select name="assignee"><option value="">Пропустити цей рядок</option>${options(state.users.filter(u=>u.access==='active'&&roles(u).includes(STAGE_ROLE[stage])),null,'name')}</select></label><label class="field">Статус<select name="status">${['planned','todo','working','review','approved'].map(k=>`<option value="${k}">${statusNames[k]}</option>`).join('')}</select></label><label class="field">Посилання на попередні файли Telegram, по одному на рядок<textarea name="links" rows="2"></textarea></label><button type="button" class="button small" data-action="import-row-remove">Прибрати рядок</button></fieldset>`;}
function importProgress(pid){progressImport=null;modal('Перенести попередній прогрес',`<form id="progress-import-form" data-project="${pid}">${field('Серія','<input name="number" type="number" min="1" max="9999" required>')}<p>Оберіть виконавців і фактичні статуси. Імпорт не перезаписує розпочату серію та не надсилає старі завдання заново. Етапи після імпорту запускаються вручну.</p><p>Старі файли зберігаються як посилання на Telegram. Для обробки або ZIP їх потрібно повторно завантажити у відповідні завдання.</p><div id="import-rows">${PIPELINE.map(importRow).join('')}</div><div class="form-actions"><select id="import-stage">${PIPELINE.map(k=>`<option value="${k}">${STAGES[k]}</option>`).join('')}</select><button type="button" class="button" data-action="import-row-add">Додати виконавця / етап</button></div>${formEnd('Перевірити імпорт')}</form>`);}
function previewProgress(f){const b=new FormData(f);const rows=[...f.querySelectorAll('[data-import-row]')].map(row=>({stage:row.querySelector('[name=stage]').value,assignee:row.querySelector('[name=assignee]').value,status:row.querySelector('[name=status]').value,links:row.querySelector('[name=links]').value.split(/\s+/).filter(Boolean)})).filter(x=>x.assignee);progressImport={type:'progress-import',project_id:f.dataset.project,data:{number:Number(b.get('number')),rows,import_id:newID()}};const next=structuredClone(state);act(next,progressImport,next.users.find(u=>u.id===state.user.id));modal('Підтвердження перенесення',`<h3>${escape(project(progressImport.project_id).title)} · Серія ${progressImport.data.number}</h3><table class="deadline-table"><thead><tr><th>Етап</th><th>Виконавець</th><th>Статус</th><th>Файли</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${STAGES[row.stage]}</td><td>${escape(user(row.assignee).name)}</td><td>${statusNames[row.status]}</td><td>${row.links.map((url,i)=>`<a href="${escape(url)}" target="_blank" rel="noopener">${i+1}</a>`).join(', ')||'—'}</td></tr>`).join('')}</tbody></table><button class="button primary" data-action="import-confirm">Підтвердити імпорт</button>`);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;try{
 const action=b.dataset.action;
 if(action==='all-modes')document.querySelectorAll('#episode-controls-form select').forEach(x=>x.value=b.dataset.value);
 if(action==='open-download')window.Telegram.WebApp.openLink(b.dataset.url,{try_instant_view:false});
 if(action==='remove-selected'){const input=$('#upload-form input[type=file]'),data=new DataTransfer();[...input.files].forEach((f,i)=>{if(i!==Number(b.dataset.index))data.items.add(f);});input.files=data.files;input.dispatchEvent(new Event('change',{bubbles:true}));}
 if(action==='batch-remove'){captureBatchRows();const i=Number(b.dataset.index);subtitleBatch.files.splice(i,1);subtitleBatch.rows.splice(i,1);$('#batch-rows').innerHTML=batchRows();}
 if(action==='delete-episode-preview'){const e=state.episodes.find(x=>x.id===b.dataset.id),ts=state.tasks.filter(t=>t.project_id===e.project_id&&t.episode===e.number);modal('Видалити серію?',`<h3>${escape(project(e.project_id).title)} · Серія ${e.number}</h3><p>Буде прибрано ${ts.length} завдань, включно із завершеними. Файли в Telegram залишаться. Ця серія більше не відновлюватиметься автоматично.</p><button class="button danger" data-action="delete-episode" data-id="${e.id}">Підтвердити видалення серії</button>`);}
 if(action==='delete-episode'){b.disabled=true;const e=state.episodes.find(x=>x.id===b.dataset.id);await workflow({type:'episode-delete',project_id:e.project_id,data:{number:e.number,confirm:e.id}});activeTaskId=null;closeSheet();await refresh();}
 if(action==='remove-take-preview'){const take=state.takes.find(v=>v.id===b.dataset.id);modal('Вилучити файл?',`<p>${escape(take.filename)}</p><p>Де видалити файл? Відповідальні отримають сповіщення про зміну.</p><div class="form-actions"><button class="button" data-close>Скасувати</button><button class="button danger" data-action="remove-take" data-id="${take.id}" data-task="${take.task_id}">Лише з додатка</button>${take.message_id?`<button class="button danger" data-action="remove-take" data-telegram="1" data-id="${take.id}" data-task="${take.task_id}">З додатка і з Telegram</button>`:""}</div>`);}
 if(action==='remove-take'){b.disabled=true;await workflow({type:'take-delete',task_id:b.dataset.task,data:{take_id:b.dataset.id,delete_telegram:b.dataset.telegram==='1'}});await finishTaskAction();}
 if(action==='import-progress')continuationStart(b.dataset.id);
 if(action==='import-row-add')$('#import-rows').insertAdjacentHTML('beforeend',importRow($('#import-stage').value));
 if(action==='import-row-remove')b.closest('[data-import-row]').remove();
 if(action==='import-confirm'){b.disabled=true;await workflow(progressImport);progressImport=null;activeTaskId=null;closeSheet();await refresh();notify('Прогрес перенесено. Перевірте ручні режими запуску серії.');}
 }catch(e){b.disabled=false;showError(e);}});

// v22: admin insight, episode reference materials and a guided continuation plan.
let analyticsProject='all',analyticsDrill=[];
const contributionFilters={episode:'all',person:'all',stage:'all',status:'all'};let contributionPage=0;
function analyticsPage(){
 if(!canAdmin())return empty('Аналітика доступна адміністраторам.');
 const a=analytics(state,analyticsProject),max=Math.max(1,...a.stages.map(x=>x.active.length));
 const stat=(key,label,n)=>`<button class="stat analytics-stat" data-action="analytics-drill" data-kind="${key}"><span>${label}</span><b>${n}</b><small>Відкрити завдання →</small></button>`;
 return heading('ПУЛЬС СТУДІЇ','Аналітика','Поточний стан команди. Натисніть показник, щоб побачити конкретні завдання.')+`<label class="field">Проєкт<select id="analytics-project"><option value="all">Уся студія</option>${options(state.projects,analyticsProject)}</select></label><div class="stats analytics-stats">${stat('active','Очікується / у роботі',a.active.length)}${stat('late','Прострочено',a.late.length)}${stat('soon','Дедлайн за 3 дні',a.soon.length)}${stat('review','На перевірці',a.review.length)}</div><div class="analytics-grid"><section class="aside-card"><h2>Де накопичилась робота</h2><p>Червоне — прострочені; сіре — решта активних.</p>${a.stages.map(x=>`<button class="analytics-bar" data-action="analytics-drill" data-stage="${x.stage}"><span>${STAGES[x.stage]} <b>${x.active.length}</b></span><span class="analytics-track"><i style="width:${x.active.length/max*100}%"><em style="width:${x.active.length?x.late.length/x.active.length*100:0}%"></em></i></span></button>`).join('')}</section><section class="aside-card"><h2>Навантаження людей</h2><p>Кількість завдань не оцінює складність роботи чи якість виконання.</p><div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Учасник</th><th>Активні</th><th>Прострочені</th><th>На перевірці</th></tr></thead><tbody>${a.people.map(p=>`<tr><th><button class="text-button" data-action="analytics-drill" data-person="${p.user.id}">${escape(p.user.name)}</button></th><td>${p.active.length}</td><td class="${p.late.length?'overdue':''}">${p.late.length}</td><td>${p.review.length}</td></tr>`).join('')}</tbody></table></div></section></div><section class="aside-card"><h2>Прогрес серій</h2><p>Завершені виробничі завдання / усі заплановані. Матеріали серії рахуються окремо.</p>${a.episodes.sort((x,y)=>x.episode.project_id.localeCompare(y.episode.project_id)||x.episode.number-y.episode.number).map(({episode:e,tasks:ts})=>{const done=ts.filter(t=>t.status==='approved').length;return `<button class="analytics-bar" data-action="analytics-drill" data-project-id="${e.project_id}" data-number="${e.number}"><span>${escape(project(e.project_id)?.title)} · ${e.number} серія <b>${done} / ${ts.length}</b></span><span class="progress-track"><i style="width:${ts.length?done/ts.length*100:0}%"></i></span><small>${e.pendingStages?.length?'Чекає ручного запуску: '+e.pendingStages.map(k=>STAGES[k]).join(', '):e.stage==='done'?'Завершено':e.started?'Виробництво триває':'Ще не розпочато'}</small></button>`;}).join('')||empty('Серій поки немає.')}</section>${contributionSection()}${creditsSection()}`;
}
function materialButton(pid,number){return pid==='general'?'':`<button class="button" data-action="episode-materials" data-project-id="${pid}" data-number="${number}">${icon('folder')}Матеріали серії</button>`;}
function episodeMaterials(pid,number){
 const e=state.episodes.find(e=>e.project_id===pid&&e.number===Number(number)),ts=state.tasks.filter(t=>t.project_id===pid&&t.episode===Number(number)&&t.material_kind);
 modal('Матеріали серії',`<p>${escape(project(pid)?.title)} · Серія ${number}</p><p>Доступні всім учасникам. Можна додавати будь-коли; виробництво не чекає цих матеріалів.</p>${Object.entries(MATERIAL_KINDS).map(([kind,name])=>{const t=ts.find(t=>t.material_kind===kind),can=t&&(canAdmin()||(t.material_editors||[t.assignee]).includes(state.user.id)),links=state.episodeMaterials.filter(x=>x.task_id===t?.id);return `<section class="aside-card"><h3>${name}</h3><p>Редактори: ${escape((t?.material_editors||[]).map(id=>user(id)?.name).join(', ')||'Лише адміністратори')}</p>${canAdmin()?`<form class="material-assignment" data-pid="${pid}" data-number="${number}" data-kind="${kind}"><label class="field">Доступ до редагування</label>${state.users.filter(u=>u.access==='active').map(u=>`<label class="checkbox"><input type="checkbox" name="editors" value="${u.id}" ${(t?.material_editors||[]).includes(u.id)?'checked':''}>${escape(u.name)}</label>`).join('')}<label></label><button class="button" type="submit">Зберегти доступ</button></form>`:''}${t?fileList(state.takes.filter(v=>v.task_id===t.id)):''}${links.map(l=>`<div class="script-download"><a href="${escape(l.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}${escape(l.name)}</a>${can?`<button class="button small" data-action="material-remove-link" data-id="${l.id}" data-task="${t.id}">Вилучити посилання</button>`:''}</div>`).join('')}${can?`<div class="form-actions wrap"><button class="button" data-action="upload" data-id="${t.id}">Додати файли</button><button class="button" data-action="material-link" data-id="${t.id}">Додати посилання (FEX тощо)</button></div>`:''}</section>`;}).join('')}`);
}
let continuationDraft=null,continuationDocs=[];
function continuationStart(pid){
 if(!canAdmin())return;const available=state.episodes.filter(e=>e.project_id===pid&&!state.tasks.some(t=>t.project_id===pid&&t.episode===e.number&&!t.independent&&t.status!=='planned'));
 modal('Перенести поточну роботу',`<form class="continuation-start" data-pid="${pid}"><p>1. Оберіть серію та місце, до якого команда дійшла вручну. Далі додамо відповідальних і файли; перед застосуванням ви перевірите підсумок.</p><label class="field">Номер серії<input name="number" type="number" min="1" max="9999" value="${available[0]?.number||1}" required></label><label class="field">Що зараз робить команда<select name="current">${Object.entries(STAGES).filter(([k])=>!['other'].includes(k)).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}<option value="done">Серію вже завершено</option></select></label><button class="button primary" type="submit">Далі: люди й файли</button></form><p>Перенесення не перезаписує вже розпочату в додатку серію. Її можна редагувати через наявні завдання.</p>`);
}
const linkLines=v=>String(v||'').split(/\s+/).filter(Boolean);
function continuationEdit(){
 const d=continuationDraft,pid=d.pid,at=PIPELINE.indexOf(d.current),stageFields=['translation','editing','casting','review','mixing'];
 const links=(name,value,label)=>`<label class="field">${label}<textarea name="${name}" rows="2" placeholder="Посилання на повідомлення Telegram або зовнішні файли — по одному в рядку">${escape((value||[]).join('\n'))}</textarea></label>`;
 modal('Люди й наявні файли',`<form class="continuation-details"><p>2. ${escape(project(pid).title)} · Серія ${d.number}. Поточний етап: <b>${STAGES[d.current]||'Завершено'}</b>.</p><p>Раніші етапи будуть завершені, наступні — заплановані. Дедлайни активних задач почнуться з моменту перенесення.</p><details><summary>Як додати файли з вашої групи</summary><p>Вставте посилання на повідомлення з файлами. Файли, які бот уже бачив, увійдуть до архівів без повторної публікації. Решта залишаться посиланнями: їх можна переслати в групу, поки бот працює, та використати нове посилання, або завантажити у завдання після перенесення. Бот не читає давню історію автоматично.</p><button type="button" class="button" data-action="import-catalog">Показати відомі боту файли</button><div id="import-catalog"></div></details>${stageFields.map(stage=>{const item=d.stages?.[stage]||{},assigned=item.assignee||state.memberships.find(m=>m.project_id===pid&&m.role===STAGE_ROLE[stage])?.user_id;return `<fieldset data-cont-stage="${stage}"><legend>${STAGES[stage]}</legend><label class="field">Відповідальний<select name="assignee" required><option value="">Оберіть людину</option>${options(state.users.filter(u=>u.access==='active'&&roles(u).includes(STAGE_ROLE[stage])),assigned,'name')}</select></label>${links('links',item.links,'Наявні файли етапу (необов’язково)')}</fieldset>`;}).join('')}<h3>Актори та їхні записи</h3><p>Для кожного актора можна вказати декілька файлів перших записів і фіксів. У полі фіксів залиште актуальну ітерацію.</p>${state.users.filter(u=>u.access==='active'&&roles(u).includes('actor')).map(u=>{const a=d.actors?.find(a=>a.id===u.id)||{include:state.memberships.some(m=>m.project_id===pid&&m.user_id===u.id&&m.role==='actor'),status:'missing'};return `<fieldset data-cont-actor="${u.id}"><legend><label><input type="checkbox" name="include" ${a.include?'checked':''}> ${escape(u.name)}</label></legend><label class="field">Що вже зроблено<select name="status">${[['missing','Ще записує / записів немає'],['unchecked','Записи є, ще не перевірено'],['clear','Перевірено, правок немає'],['fix','Є правки, чекаємо запис'],['fixed','Правки вже здано']].map(([k,v])=>`<option value="${k}" ${a.status===k?'selected':''}>${v}</option>`).join('')}</select></label>${links('scripts',a.scripts,'Індивідуальні субтитри')}${links('recordings',a.recordings,'Перші записи (усі файли цього актора)')}${links('fixes',a.fixes,'Актуальні фікси')}<label class="field">Ітерація фіксів<input type="number" name="iteration" min="1" max="99" value="${a.iteration||1}"></label></fieldset>`;}).join('')}<button class="button primary" type="submit">Далі: перевірити перенесення</button></form>`);
}
async function continuationPreview(form){
 const d=continuationDraft;d.stages=Object.fromEntries([...form.querySelectorAll('[data-cont-stage]')].map(row=>[row.dataset.contStage,{assignee:row.querySelector('[name=assignee]').value,links:linkLines(row.querySelector('[name=links]').value)}]));d.actors=[...form.querySelectorAll('[data-cont-actor]')].map(row=>({id:row.dataset.contActor,include:row.querySelector('[name=include]').checked,status:row.querySelector('[name=status]').value,scripts:linkLines(row.querySelector('[name=scripts]').value),recordings:linkLines(row.querySelector('[name=recordings]').value),fixes:linkLines(row.querySelector('[name=fixes]').value),iteration:Number(row.querySelector('[name=iteration]').value)}));
 const rows=continuationRows(state,d.pid,d.current,d.stages,d.actors);d.action={type:'progress-import',project_id:d.pid,data:{number:d.number,current:d.current,rows,import_id:d.id,guided:true}};
 const next=structuredClone(state);act(next,d.action,next.users.find(u=>u.id===state.user.id));
 if(!demo)continuationDocs=(await api('/import-documents')).files;
 const known=url=>{try{const p=parseTelegramLink(url);return continuationDocs.find(x=>String(x.chat_id)===p.chatId&&x.message_id===p.messageId);}catch{return null;}};
 modal('Перевірте перед перенесенням',`<p>3. ${escape(project(d.pid).title)} · Серія ${d.number}</p><div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Етап / людина</th><th>Стан після перенесення</th><th>Матеріали</th></tr></thead><tbody>${rows.map(r=>`<tr><th>${STAGES[r.stage]}<br>${escape(user(r.assignee)?.name)}</th><td>${badge(r.status)}</td><td>${r.links.map(url=>`<p><a href="${escape(url)}" target="_blank" rel="noopener">${escape(known(url)?.filename||url)}</a><small>${known(url)?'Файл доступний боту — додасться до завдання й ZIP':'Лише посилання — без ZIP; файл можна додати пізніше'}</small></p>`).join('')||'Немає файлів'}${r.scripts?.length?'<p>Індивідуальних субтитрів: '+r.scripts.length+'</p>':''}</td></tr>`).join('')}</tbody></table></div><p>Старі файли не публікуються повторно. Повідомлення отримають лише виконавці активних завдань. Наступні етапи запускатимуться автоматично, наступна серія — вручну.</p><div class="form-actions"><button class="button" data-action="continuation-back">Виправити</button><button class="button primary" data-action="continuation-apply">Перенести й продовжити роботу</button></div>`);
}

document.addEventListener('change',e=>{if(e.target.id==='analytics-project'){analyticsProject=e.target.value;contributionFilters.episode='all';contributionPage=0;renderMain();}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.matches('.material-assignment,.material-link-form,.continuation-start,.continuation-details'))return;e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;const data=Object.fromEntries(new FormData(form));try{
 if(form.matches('.material-assignment')){await workflow({type:'material-assign',project_id:form.dataset.pid,data:{number:Number(form.dataset.number),kind:form.dataset.kind,editors:new FormData(form).getAll('editors')}});episodeMaterials(form.dataset.pid,form.dataset.number);}
 if(form.matches('.material-link-form')){await workflow({type:'material-link',task_id:form.dataset.task,data});const t=state.tasks.find(t=>t.id===form.dataset.task);episodeMaterials(t.project_id,t.episode);updateNoticeBell();}
 if(form.matches('.continuation-start')){continuationDraft={pid:form.dataset.pid,number:Number(data.number),current:data.current,id:newID()};continuationEdit();}
 if(form.matches('.continuation-details'))await continuationPreview(form);
 }catch(error){showError(error);}finally{button.disabled=false;}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
 if(action==='transfers')transfersModal();
 if(action==='transfer-retry'){const x=transferQueue.find(x=>x.id===b.dataset.id);if(x.status!=='failed')return;x.status='queued';x.message='';updateTransfers();void pumpTransfers();}
 if(action==='transfer-cancel'){const x=transferQueue.find(x=>x.id===b.dataset.id);if(!x||!['queued','failed'].includes(x.status))return;x.status='cancelled';x.message='';updateTransfers();}
 if(action==='episode-materials')episodeMaterials(b.dataset.projectId,b.dataset.number);
 if(action==='material-link')modal('Додати посилання',`<form class="material-link-form" data-task="${b.dataset.id}"><label class="field">Назва<input name="name" maxlength="200" required></label><label class="field">HTTPS-посилання<input name="url" type="url" maxlength="2000" placeholder="https://fex.net/…" required></label><p>Зовнішній файл не копіюється на сервер і не входить до ZIP. Переконайтеся, що команда має доступ і посилання не прострочене.</p><button class="button primary" type="submit">Додати</button></form>`);
 if(action==='material-remove-link'){if(!confirm('Вилучити посилання з матеріалів серії? Зовнішній файл залишиться.'))return;await workflow({type:'material-link-delete',task_id:b.dataset.task,data:{id:b.dataset.id}});const t=state.tasks.find(t=>t.id===b.dataset.task);episodeMaterials(t.project_id,t.episode);}
 if(action==='analytics-drill'){if(!canAdmin())return;const a=analytics(state,analyticsProject);let ts=b.dataset.kind?a[b.dataset.kind]:b.dataset.person?a.tasks.filter(t=>t.assignee===b.dataset.person&&t.status!=='approved'):b.dataset.stage?a.active.filter(t=>t.stage===b.dataset.stage):state.tasks.filter(t=>t.project_id===b.dataset.projectId&&t.episode===Number(b.dataset.number));modal('Завдання за показником',taskTable(ts,true));}
 if(action==='continuation-back')continuationEdit();
 if(action==='continuation-apply'){b.disabled=true;await workflow(continuationDraft.action);activeTaskId=null;inTaskView=false;closeSheet();await refresh();notify('Прогрес перенесено. Активні завдання призначено виконавцям.');continuationDraft=null;}
 if(action==='import-catalog'){b.disabled=true;continuationDocs=demo?[]:(await api('/import-documents')).files;$('#import-catalog').innerHTML='<label class="field">Знайти файл<input id="catalog-search" placeholder="Назва проєкту, серія або нік"></label><div id="catalog-rows"></div><button type="button" class="button" data-action="catalog-apply">Додати вибрані до полів майстра</button>';renderImportCatalog();b.disabled=false;}
 }catch(error){b.disabled=false;showError(error);}});

function renderImportCatalog(){const query=($('#catalog-search')?.value||'').toLowerCase(),d=continuationDraft;const targets=[...['translation','editing','casting','review','mixing'].map(stage=>[stage+':links',STAGES[stage]]),...state.users.filter(u=>u.access==='active'&&roles(u).includes('actor')).flatMap(u=>[['scripts','Субтитри'],['recordings','Перші записи'],['fixes','Фікси']].map(([key,label])=>[u.id+':'+key,u.name+' · '+label]))];$('#catalog-rows').innerHTML=continuationDocs.map((f,i)=>({f,i})).filter(({f})=>f.filename.toLowerCase().includes(query)).slice(0,50).map(({f,i})=>{const matches=matchSubtitle(state,f.filename,d.pid),audio=/\.(wav|flac)$/i.test(f.filename);let guess=matches.length===1?matches[0]+':'+(audio?/_FIX\d*(?:[_.]|$)/i.test(f.filename)?'fixes':'recordings':'scripts'):' ';if(/_Translate(?:[_.]|$)/i.test(f.filename))guess='translation:links';if(/_Edit(?:[_.]|$)/i.test(f.filename))guess='editing:links';return `<label class="field">${escape(f.filename)}<select data-catalog-file="${i}"><option value="">Не додавати</option>${targets.map(([v,label])=>`<option value="${v}" ${guess===v?'selected':''}>${escape(label)}</option>`).join('')}</select></label>`;}).join('')+'<small>Показано до 50 збігів. Перевірте розпізнані призначення перед додаванням.</small>';}
document.addEventListener('input',e=>{if(e.target.id==='catalog-search')renderImportCatalog();});
document.addEventListener('click',e=>{if(!e.target.closest('[data-action=catalog-apply]'))return;let count=0;for(const select of document.querySelectorAll('[data-catalog-file]')){if(!select.value)continue;const split=select.value.lastIndexOf(':'),id=select.value.slice(0,split),field=select.value.slice(split+1),f=continuationDocs[Number(select.dataset.catalogFile)],row=[...document.querySelectorAll('[data-cont-stage],[data-cont-actor]')].find(r=>r.dataset.contStage===id||r.dataset.contActor===id),input=row?.querySelector(`[name="${field}"]`);if(!input)continue;const url=`https://t.me/c/${String(f.chat_id).replace(/^-100/,'')}/${f.thread_id||1}/${f.message_id}`;input.value=[...new Set([...linkLines(input.value),url])].join('\n');if(row.querySelector('[name=include]'))row.querySelector('[name=include]').checked=true;count++;}notify('Додано посилань: '+count+'. Перевірте статуси акторів нижче.');});

function contributionSection(){
 const rows=contributionMatrix(state,{project:analyticsProject,...contributionFilters}),perPage=30,pages=Math.max(1,Math.ceil(rows.length/perPage));contributionPage=Math.min(contributionPage,pages-1);
 const scope=state.tasks.filter(t=>analyticsProject==='all'||t.project_id===analyticsProject),people=new Set(scope.map(t=>t.assignee)),episodes=[...new Set(rows.map(r=>r.number).concat(state.episodes.filter(e=>analyticsProject==='all'||e.project_id===analyticsProject).map(e=>e.number)))].sort((a,b)=>a-b);
 const select=(key,label,items)=>`<label class="field">${label}<select data-contribution-filter="${key}"><option value="all">Усі</option>${items.map(([v,l])=>`<option value="${escape(v)}" ${contributionFilters[key]===String(v)?'selected':''}>${escape(l)}</option>`).join('')}</select></label>`;
 const mark=t=>t.admin_closed?['closed','−','Закрито адміністратором']:t.status==='approved'?['done','✓','Завершено']:t.status==='review'?['review','◷','На перевірці']:t.status==='working'?['working','◐','У роботі']:['pending','□',statusNames[t.status]||'Очікується'];
 const cell=c=>`<td class="${c.complete?'matrix-complete':''}">${c.tasks.length?c.tasks.map(t=>{const [kind,symbol,label]=mark(t);return `<button class="matrix-person ${kind}" data-action="task-detail" data-id="${escape(t.id)}" title="${escape(label)}${t.import_id?' · Перенесений прогрес':''}"><span class="matrix-check" aria-hidden="true">${symbol}</span><span>${escape(user(t.assignee)?.name||'Не призначено')}${t.stage==='correction'?'<small>FIX'+(t.fix_iteration>1?t.fix_iteration:'')+'</small>':''}<span class="matrix-status">${label}</span></span></button>`;}).join(''):'<span class="matrix-empty" title="Завдань немає">—</span>'}</td>`;
 const visible=rows.slice(contributionPage*perPage,(contributionPage+1)*perPage),groups=[...new Set(visible.map(r=>r.project_id))];
 return `<section class="aside-card contribution-section"><h2>Хто що зробив</h2><p>Серії по рядках, етапи по стовпчиках. Галочки оновлюються зі статусів завдань. Натисніть на виконавця, щоб відкрити завдання.</p><div class="contribution-filters matrix-filters">${select('episode','Серія',episodes.map(n=>[n,n]))}${select('person','Виконавець',state.users.filter(u=>people.has(u.id)).map(u=>[u.id,u.name]))}</div><div class="matrix-legend"><span>✓ Завершено</span><span>◷ На перевірці</span><span>◐ У роботі</span><span>□ Очікується / заплановано</span><span>− Закрито адміном</span><span>— Немає завдань</span></div>${groups.map(pid=>`<h3 class="matrix-project">${escape(project(pid)?.title||'Проєкт недоступний')} <small>Сезон ${escape(project(pid)?.season||1)}</small></h3><div class="deadline-scroll matrix-scroll" tabindex="0" role="region" aria-label="Прогрес серій ${escape(project(pid)?.title)}"><table class="contribution-matrix"><thead><tr><th scope="col">Серія / %</th>${PIPELINE.map(k=>`<th scope="col">${escape(STAGES[k])}</th>`).join('')}</tr></thead><tbody>${visible.filter(r=>r.project_id===pid).map(r=>`<tr><th scope="row">${r.number} серія<small title="Завершено ${r.done} з ${r.total} завдань усієї серії">${r.percent}% · ${r.done}/${r.total}</small></th>${r.cells.map(cell).join('')}</tr>`).join('')}</tbody></table></div>`).join('')||empty('За цими фільтрами серій немає.')}<div class="form-actions contribution-pagination"><button class="button small" data-action="contribution-prev" ${contributionPage===0?'disabled':''}>← Назад</button><span>Сторінка ${contributionPage+1} з ${pages}</span><button class="button small" data-action="contribution-next" ${contributionPage+1>=pages?'disabled':''}>Далі →</button></div><small>Відсоток — виконані завдання всієї серії, без закритих адміністратором. Матеріали серії та загальні завдання не входять у виробничу таблицю.</small></section>`;
}
document.addEventListener('change',e=>{const key=e.target.dataset.contributionFilter;if(!key||!canAdmin())return;contributionFilters[key]=e.target.value;contributionPage=0;renderMain();});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!canAdmin())return;if(b.dataset.action==='contribution-prev'||b.dataset.action==='contribution-next'){contributionPage+=b.dataset.action==='contribution-next'?1:-1;renderMain();}});

function timezoneForm(){const z=userZone(state,state.user.id);return `<form id="timezone-form" class="aside-card"><h2>Часовий пояс</h2><p>Дедлайни показуються за поясом виконавця. За замовчуванням — Київ.</p><label class="field">Часовий пояс<select name="zone">${[...new Set(['Europe/Kyiv',...(Intl.supportedValuesOf?Intl.supportedValuesOf('timeZone'):['Europe/Kyiv','Europe/Berlin','Europe/Rome','UTC']),z])].map(v=>`<option value="${v}" ${v===z?'selected':''}>${v}</option>`).join('')}</select></label><button type="button" class="button" data-action="local-timezone">Визначити з пристрою</button>${formEnd('Зберегти часовий пояс')}</form>`;}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="local-timezone"]'))document.querySelector('#timezone-form [name=zone]').value=Intl.DateTimeFormat().resolvedOptions().timeZone;});

async function notionImages(){
 const nodes=[...document.querySelectorAll('[data-notion-asset]')];
 for(const img of nodes){try{const response=await api('/notion/assets/'+img.dataset.notionAsset,{raw:true});const objectURL=URL.createObjectURL(await response.blob());if(!img.isConnected){URL.revokeObjectURL(objectURL);continue;}img.onload=()=>URL.revokeObjectURL(objectURL);img.onerror=()=>URL.revokeObjectURL(objectURL);img.src=objectURL;}catch{img.alt='Не вдалося завантажити зображення. Відкрийте правки повторно.';}}
}
async function notionImportForm(taskId,uid){
 if(demo){modal('Правки з Notion', '<p>Імпорт доступний на вашому сервері після підключення бази Notion. У деморежимі приватні дані Notion не завантажуються.</p><button class="button" data-action="review-back" data-id="'+escape(taskId)+'">Назад до перевірки</button>');return;}
 const data=await api('/notion/views'),old=notionDrafts.get(taskId+':'+uid);
 modal('Правки для '+escape(user(uid)?.name),`<form id="notion-import-form" data-task="${escape(taskId)}" data-user="${escape(uid)}"><p>Оберіть вкладку з потрібним тайтлом і серією. Застосовуються збережені фільтри Notion; локальні незбережені фільтри не враховуються.</p><label class="field">Вкладка / board view<select name="view_id" required><option value="">Оберіть вкладку</option>${data.views.map(v=>`<option value="${escape(v.id)}" ${v.id===old?.view.id?'selected':''}>${escape(v.name)} · ${escape(v.id.slice(-6))}</option>`).join('')}</select></label><label class="field">Псевдонім актора в Notion<input name="alias" maxlength="150" value="${escape(old?.alias||user(uid)?.name)}" required></label><details><summary>Інше поле для псевдоніма</summary><p>За замовчуванням — поле, за яким згруповані колонки board view.</p><input name="actor_property" aria-label="Назва поля псевдоніма" value="${escape(old?.actor_property||'')}" placeholder="Наприклад, Актор"></details><p>Імпорт створить копію. Актор отримає її після підтвердження «Сповістити акторів». У Notion нічого не зміниться.</p><button type="submit" class="button primary">Завантажити й перевірити</button><button type="button" class="button" data-action="review-back" data-id="${escape(taskId)}">Назад</button></form>`);
}
document.addEventListener('submit',async e=>{
 if(e.target.id!=='notion-import-form')return;e.preventDefault();const f=e.target,b=f.querySelector('[type=submit]');b.disabled=true;b.textContent='Копіюємо картки й зображення…';
 try{const data=await api('/notion/import',{method:'POST',data:{...Object.fromEntries(new FormData(f)),task_id:f.dataset.task,actor_id:f.dataset.user}});notionPreview={task:f.dataset.task,user:f.dataset.user,data};modal('Перевірте правки й одержувача',`<p><b>${escape(user(f.dataset.user)?.name)}</b> · ${escape(project(state.tasks.find(t=>t.id===f.dataset.task).project_id)?.title)} · Серія ${state.tasks.find(t=>t.id===f.dataset.task).episode}</p><p>Перевірте, що всі картки стосуються цієї серії та цього актора.</p>${renderNotion(data)}<div class="form-actions"><button class="button" data-action="notion-import" data-id="${escape(f.dataset.task)}" data-user="${escape(f.dataset.user)}">Виправити вибір</button><button class="button primary" data-action="notion-accept">Прикріпити ці правки</button></div>`);void notionImages();}catch(error){showError(error);}finally{b.disabled=false;b.textContent='Завантажити й перевірити';}
});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{
 if(b.dataset.action==='notion-import'){b.disabled=true;await notionImportForm(b.dataset.id,b.dataset.user);}
 if(b.dataset.action==='notion-accept'&&notionPreview){const {task,user:uid,data}=notionPreview;notionDrafts.set(task+':'+uid,data);reviewDrafts.set(task,{...(reviewDrafts.get(task)||{}),[uid]:'fix'});notionPreview=null;productionTask(state.tasks.find(t=>t.id===task));}
 if(b.dataset.action==='notion-read'){b.disabled=true;const data=await api('/notion/snapshots/'+b.dataset.id);modal('Правки · '+escape(data.alias),`<button class="button" data-action="task-detail" data-id="${escape(b.dataset.task)}">Назад до завдання</button>${renderNotion(data)}`);void notionImages();}
 }catch(error){showError(error);}finally{b.disabled=false;}});

function quietRange(r={start:'22:00',end:'08:00',mode:'silent'}){return `<div class="quiet-range aside-card"><div class="form-grid">${field('Початок',`<input type="time" name="start" value="${escape(r.start)}" required>`)}${field('Завершення',`<input type="time" name="end" value="${escape(r.end)}" required>`)}</div>${field('У цей час',`<select name="mode"><option value="silent" ${r.mode==='silent'?'selected':''}>Надсилати без звуку</option><option value="pause" ${r.mode==='pause'?'selected':''}>Не надсилати до завершення проміжку</option></select>`)}<button type="button" class="button small" data-action="quiet-remove">Видалити проміжок</button></div>`;}
function quietHoursModal(){const p=state.profiles.find(p=>p.user_id===state.user.id)?.quiet_hours||{enabled:false,ranges:[]};modal('Не турбувати',`<form id="quiet-hours-form"><p>Щодня за часовим поясом ${escape(userZone(state,state.user.id))}. Його можна змінити в налаштуваннях акаунта.</p><label><input type="checkbox" name="enabled" ${p.enabled?'checked':''}> Увімкнути «Не турбувати»</label><div id="quiet-ranges">${(p.ranges.length?p.ranges:[{start:'22:00',end:'08:00',mode:'silent'}]).map(quietRange).join('')}</div><button type="button" class="button" data-action="quiet-add">+ Проміжок</button><p class="subtitle">Проміжок може переходити через північ. Сповіщення завжди доступні в додатку. Призупинені повідомлення надійдуть одним повідомленням після завершення проміжку, якщо їх ще не прочитано. При перетині проміжків призупинення має пріоритет.</p>${formEnd('Зберегти')}`);}

function accessQueue(){if(!canAdmin())return '';const pending=state.users.filter(u=>u.access==='pending');return `<section class="aside-card"><h2>Заявки на доступ · ${pending.length}</h2><p>Заявка створюється після підтвердження особи через Telegram. Після схвалення учасник має повторити вхід; також потрібна участь у групі студії.</p>${pending.map(u=>`<article class="notification-card"><strong>${escape(u.name)}</strong><p>${escape(u.username?'@'+u.username:u.id)} · ID ${escape(u.id)}</p><div class="form-actions wrap"><button class="button primary" data-action="access-approve" data-id="${u.id}">Надати доступ</button><button class="button" data-action="edit-user" data-id="${u.id}">Ролі та доступ</button><button class="button" data-action="access-reject" data-id="${u.id}">Відхилити</button></div></article>`).join('')||'<p>Нових заявок немає.</p>'}</section>`;}
function creditsSection(){const rows=state.voiceCredits.filter(c=>analyticsProject==='all'||c.project_id===analyticsProject);return `<section class="aside-card"><h2>Хто кого озвучував</h2><p>Ручний облік персонажів. Ці записи не створюють завдань і не змінюють виробництво.</p><button class="button primary" data-action="credit-edit">Додати запис</button><div class="deadline-scroll"><table class="deadline-table"><thead><tr><th>Учасник</th><th>Проєкт</th><th>Персонаж</th><th>Примітка</th><th>Дії</th></tr></thead><tbody>${rows.sort((a,b)=>(user(a.user_id)?.name||'').localeCompare(user(b.user_id)?.name||'','uk')).map(c=>`<tr><td>${escape(user(c.user_id)?.name||c.user_id)}</td><td>${escape(c.project_title||project(c.project_id)?.title||c.project_id)}</td><td>${escape(c.character)}</td><td>${escape(c.note||'')}</td><td><button class="button small" data-action="credit-edit" data-id="${c.id}">Змінити</button><button class="button small" data-action="credit-delete" data-id="${c.id}">Видалити</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('Записів поки немає.')}</section>`;}
function creditModal(id){const c=state.voiceCredits.find(x=>x.id===id)||{},external=!!c.project_title,selected=external?'external':c.project_id||analyticsProject;modal(c.id?'Редагувати озвучену роль':'Додати озвучену роль',`<form id="credit-form" data-id="${c.id||''}">${field('Учасник',`<select name="user_id" required>${options(state.users,c.user_id,'name')}</select>`)}${field('Проєкт',`<select name="project_id" id="credit-project" required><option value="external" ${external?'selected':''}>Інший проєкт — лише для статистики</option>${options(state.projects.filter(p=>p.id!=='general'),selected)}</select>`)}<div id="credit-external">${field('Назва проєкту для статистики',`<input name="project_title" value="${escape(c.project_title||'')}" maxlength="200">`)}<p>Ця назва зберігається лише тут. Проєкт не з’явиться в робочому списку, завдання не створюються.</p></div>${field('Персонаж',`<input name="character" value="${escape(c.character||'')}" maxlength="200" required>`)}${field('Примітка (серії, сезон — необов’язково)',`<textarea name="note" maxlength="1000">${escape(c.note||'')}</textarea>`)}${formEnd('Зберегти')}`);syncCreditProject();}
function syncCreditProject(){const select=$('#credit-project'),box=$('#credit-external');if(!select||!box)return;const external=select.value==='external';box.hidden=!external;box.querySelector('input').required=external;}
document.addEventListener('change',e=>{if(e.target.id==='credit-project')syncCreditProject();});
